 if(index===2)art=`<path fill="${dark}" d="M15 30h30v6h5v8h4v16H6V44h4v-8h5z"/><path fill="#754c9d" d="M16 34h28v8h5v14H11V42h5z"/><path fill="${coat}" d="M23 33h16v24H19V42h4z"/><path fill="${skin}" d="M20 22h23v17H20z"/><path fill="${dark}" d="M29 3h15v6h-7v8h7v6h6v6H11v-6h9V12h9z"/><path fill="${coat}" d="M32 7h6v3h-5v9h8v5H22v-9h10z"/><path fill="${trim}" d="M18 24h29v3H18zM29 42h5v5h-5zM53 23h4v36h-4z"/><path fill="${dark}" d="M51 8h8v4h4v11h-4v4h-8v-4h-4V12h4z"/><path fill="#8adce8" d="M52 12h6v4h2v4h-2v3h-6v-3h-2v-4h2z"/><path class="companion-crystal" fill="#eaffff" d="M52 13h3v6h-3z"/><path class="companion-glint" fill="#eaffff" d="M59 7h2v2h-2z"/>`;
