function evolutionPanel(r){const e=evolutionStage(r.xp);return `<section class="evolutionpanel"><div class="evolutioncurrent">${companionArt(e.index)}<div><h3>${e.name}</h3><p>${e.detail}</p><b>${e.next?`${e.next.xp-r.xp} XP until ${e.next.name}`:'Final form unlocked!'}</b><p class="caption">Visual evolution is for fun—not an exam-readiness score.</p></div></div><div class="evolutionpath">${EVOLUTIONS.map((s,i)=>`<div class="evolutionstep ${i===e.index?'current':''} ${i>e.index?'locked':''}">${companionArt(i)}<b>${s.name}</b><small>${s.xp} XP${i<=e.index?' · ✓':''}</small></div>`).join('')}</div></section>`;}

const CHOICE_SKILLS={structure:'choiceStructure',fromcode:'choiceName',three:'choiceThree',one:'choiceOne'};
const choiceSkills=Object.values(CHOICE_SKILLS);
function practiceSkill(kind,format){return format==='choice'&&CHOICE_SKILLS[kind]?CHOICE_SKILLS[kind]:quizSkill(kind);}
function choosePracticeFormat(format){if(!['choice','typed'].includes(format))return;progress.practiceFormat=format;setup();}
function prepareAnswerFormat(q){if(round.hardOverride&&!round.quest&&!round.exam){q.answerFormat='typed';q.difficulty=null;}if(!round.quest&&!round.exam&&q.kind!=='contrast'&&!q.answerFormat&&!round.format&&progress.practiceFormat==='choice'&&window.AminoQuestEngine?.chooseDifficulty){q.difficulty=window.AminoQuestEngine.chooseDifficulty({item:adaptiveItem(q.a),kind:q.kind,now:Date.now(),fluency:progress.fluency});q.answerFormat=q.difficulty.answerFormat;}const c=round.quest?questRun().current:null;q.answerFormat=round.exam||q.kind==='contrast'?'typed':c?(c.answerFormat||questStage().answerFormat||'typed'):(q.answerFormat||round.format||progress.practiceFormat);q.optionIds=c?[...c.optionIds]:(q.optionIds||[]);q.choiceViewed=c?c.choiceViewed:!!q.choiceViewed;if(q.answerFormat==='choice'){if(q.optionIds.length>4){const keep=new Set([q.a.one,...q.optionIds.filter(id=>id!==q.a.one).slice(0,3)]);q.optionIds=q.optionIds.filter(id=>keep.has(id));}const catalog=q.optionIds.length===4?AMINO.filter(a=>q.optionIds.includes(a.one)):AMINO;const generated=window.AminoDistractors.createAnswerOptions({aminoAcid:q.a,kind:q.kind,aminoAcids:catalog});q.options=q.optionIds.length===4?q.optionIds.map(id=>generated.find(o=>o.id===id)):generated;q.optionIds=q.options.map(o=>o.id);q.choiceViewed=true;if(c){c.answerFormat='choice';c.optionIds=[...q.optionIds];c.choiceViewed=true;c.assisted=!!q.assisted;save();}const keys=q.kind==='one'?['one']:q.kind==='three'?['three']:['name'];for(const option of q.options)expose(AMINO.find(a=>a.one===option.id),keys,{choicePrompt:true});}else if(c){c.answerFormat='typed';save();}}
function answerControls(q){const format=round.exam||round.quest||q.kind==='contrast'?'':`<div class="answerformats" role="group" aria-label="Answer format"><button class="btn light ${q.answerFormat==='choice'?'selected':''}" id="formatChoice" ${round.hardOverride?'disabled':''} aria-pressed="${q.answerFormat==='choice'}">4 choices</button><button class="btn light ${q.answerFormat==='typed'?'selected':''}" id="formatTyped" aria-pressed="${q.answerFormat==='typed'}">Hard mode</button></div>`;return format+(q.answerFormat==='choice'?`<div class="answerchoices" role="group" aria-label="Four answer choices">${q.options.map((o,i)=>`<button class="answerchoice" data-choice="${o.id}"><span class="choiceindex">${i+1}</span><b class="${['one','three'].includes(q.kind)?'code-label':''}">${o.label}</b></button>`).join('')}</div><p class="caption answerstyle">Recognition with choices · tracked separately from typed recall</p><form id="answerForm" hidden><input id="answer" aria-label="Your answer"><button id="check">Check answer</button></form>`:`<form id="answerForm"><div class="inputrow"><input id="answer" class="${['one','three'].includes(q.kind)?'answer-code':''}" autocomplete="off" autocorrect="off" autocapitalize="off" spellcheck="false" aria-label="Your answer" placeholder="${['three','one'].includes(q.kind)?'Type the code':'Type the full name'}"><button class="btn" id="check">${round.exam?'Save answer':'Check answer'}</button></div></form>`);}
function bindAnswerControls(q){if(!round.exam&&!round.quest&&q.kind!=='contrast'){$('#formatChoice').onclick=()=>switchAnswerFormat('choice');$('#formatTyped').onclick=()=>switchAnswerFormat('typed');}document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{if(round.locked)return;const option=q.options.find(o=>o.id===b.dataset.choice);if(option)answer(option.label);});}
function switchAnswerFormat(format){if(!round||round.exam||round.quest||round.locked||!['choice','typed'].includes(format))return;if(round.hardOverride&&format==='choice')return;const q=round.items[round.i];if(format==='typed'){round.hardOverride=true;round.format='typed';if($('#formatChoice'))$('#formatChoice').disabled=true;}if(q.answerFormat===format)return;if(!q.assisted)noteResponseSupport(q);stopResponseTiming();if(format==='typed'&&q.choiceViewed||format==='choice')q.assisted=true;if(round.focus&&q.assisted)invalidateFocusCurrent();q.answerFormat=format;if(round.quest){const c=questRun().current;c.answerFormat=format;c.assisted=q.assisted;c.optionIds=[...(q.optionIds||[])];c.choiceViewed=!!q.choiceViewed;save();}question(true);}
function lockAnswerControls(q){$('.questionpanel').classList.toggle('answered',true);for(const id of ['#formatChoice','#formatTyped'])if($(id))$(id).disabled=true;document.querySelectorAll('[data-choice]').forEach(b=>{b.disabled=true;b.classList.toggle('correct',b.dataset.choice===q.a.one);});}
let dashboardView=null;

const recallSkills=['structure','name','three','one'];
function skill(a,k){const name=typeof a==='string'?a:a.name;progress.skills[name]=progress.skills[name]||{};const t=progress.skills[name][k]||(progress.skills[name][k]={streak:0,right:0,wrong:0});for(const f of ['lastAttempt','lastExposure','nextDue','lastQuestion','missQuestion','delayedSuccess','confidentMisses','hinted','recovered','retainedChecks','assemblyAward'])t[f]??=(f==='retainedChecks'&&t.wrong===0?(t.delayedSuccess||0):0);return t;}
function record(a,k,ok,opts={}){if(progress.focusState&&typeof invalidateFocusEvidence==='function'&&(!ok||(opts.hinted&&k!=='draw')))invalidateFocusEvidence(a.one,k);const t=skill(a,k),now=opts.now??Date.now(),previousWrong=t.wrong&&t.streak===0;if(opts.hinted){t.hinted++;t.lastExposure=now;t.nextDue=now+120000;if(!t.lastAttempt)t.lastAttempt=now;save();return {delayed:false,assisted:true};}progress.reviewCounter=(progress.reviewCounter||0)+1;const seq=progress.reviewCounter;const delayed=opts.retentionEligible!==false&&!opts.hinted&&k!=='draw'&&t.lastAttempt>0&&t.nextDue>0&&now>=t.nextDue&&now-Math.max(t.lastAttempt,t.lastExposure)>=120000&&(now-Math.max(t.lastAttempt,t.lastExposure)>=21600000||!t.missQuestion||otherReviews(a,t.lastQuestion,1)>=3);let passed=false;
 if(opts.hinted){t.hinted++;t.lastExposure=now;t.nextDue=now+120000;if(!t.lastAttempt)t.lastAttempt=now;save();return {delayed:false,assisted:true};}
 t.streak=ok?t.streak+1:0;t[ok?'right':'wrong']++;
 if(ok&&delayed){t.delayedSuccess++;t.retainedChecks++;t.missQuestion=0;passed=true;if(t.wrong&&t.retainedChecks===1)t.recovered=1;t.nextDue=now+(t.retainedChecks===1?600000:86400000);}
 else if(!ok){t.retainedChecks=0;t.nextDue=now+120000;t.missQuestion=seq;if(opts.confidence==='know')t.confidentMisses++;}
 else if(!t.nextDue)t.nextDue=now+120000;
 t.lastAttempt=now;t.lastQuestion=seq;progress.recentReviews=[...(progress.recentReviews||[]),typeof a==='string'?a:a.name].slice(-100);
 const name=typeof a==='string'?a:a.name;if(!ok&&!progress.missed.includes(name))progress.missed.push(name);if(ok&&[...recallSkills,...choiceSkills,'draw','contrast'].every(k=>{const z=skill(a,k);return !(z.wrong&&z.streak===0);}))progress.missed=progress.missed.filter(n=>n!==name);save();return {delayed:passed,assisted:false};}
function otherReviews(a,last,offset=0){const name=typeof a==='string'?a:a.name;const count=Math.max(0,(progress.reviewCounter||0)-last-offset);if(!count)return 0;return (progress.recentReviews||[]).slice(-Math.min(count,100)).filter(n=>n!==name).length;}
function expose(a,keys=recallSkills,opts={}){if(round?.focus&&typeof focusExposure==='function')focusExposure(a,keys,opts);const r=progress.questRun,s=r?.queue[r.index],k=s?quizSkill(s.kind):null;if(r&&!r.complete&&!r.current.answered&&!(opts.choicePrompt&&mode==='quest'&&!r.paused&&round?.quest&&round.items[0]?.answerFormat==='choice')&&s.code===a.one&&recallSkills.includes(k)&&(keys.includes(k)||(k==='structure'&&keys.includes('name')))){if(!r.current.assisted)noteResponseSupport({a,kind:s.kind,answerFormat:r.current.answerFormat||s.answerFormat||'typed'});r.current.assisted=true;if(round?.quest&&round.items[0]?.a.one===a.one)round.items[0].assisted=true;}for(const k of keys){const t=skill(a,k);t.lastExposure=Date.now();if(t.nextDue)t.nextDue=Math.max(t.nextDue,t.lastExposure+120000);}save();}
function weakScore(a,k){const t=skill(a,k);return (t.wrong&&t.streak===0?-5:0)-Math.min(t.confidentMisses,3)+(t.nextDue&&t.nextDue<=Date.now()?-2:0)+Math.min(t.streak,3);}
function dueItems(now=Date.now()){return AMINO.flatMap(a=>recallSkills.filter(k=>{const t=skill(a,k);return t.nextDue>0&&t.nextDue<=now&&now-Math.max(t.lastAttempt,t.lastExposure)>=120000&&(now-Math.max(t.lastAttempt,t.lastExposure)>=21600000||!t.missQuestion||otherReviews(a,t.lastQuestion)>=3);}).map(k=>({a,kind:k==='name'?'fromcode':k})));}
const RECALL_LEVELS=['New','Learning','Recalled unaided','Remembered later','Well practiced'];
const SKILL_NAMES={structure:'structure recognition',name:'full name',three:'3-letter code',one:'1-letter code',draw:'drawing (self-rated)',forge:'building (scaffolded)',choiceStructure:'structure (four choices)',choiceName:'full name (four choices)',choiceThree:'3-letter code (four choices)',choiceOne:'1-letter code (four choices)'};
function aminoLevel(a){const skills=recallSkills.map(k=>skill(a,k));const used=Object.keys(SKILL_NAMES).some(k=>{const t=skill(a,k);return t.right+t.wrong+t.hinted+t.lastAttempt+t.lastExposure>0;});const independent=skills.every(t=>t.streak>0);let index=used?1:0;if(independent)index=2;if(independent&&skills.every(t=>t.retainedChecks>=1))index=3;if(independent&&skills.every(t=>t.retainedChecks>=2))index=4;let next;if(index<2){const missing=recallSkills.filter(k=>skill(a,k).streak===0);next='Next: recall '+missing.map(k=>SKILL_NAMES[k]).join(', ')+' correctly without hints.';}else if(index<4){const target=index===2?1:2;next='Next: '+(target===1?'a':'a second')+' delayed check for '+recallSkills.filter(k=>skill(a,k).retainedChecks<target).map(k=>SKILL_NAMES[k]).join(', ')+'.';}else next='Keep reviewing before the exam; practice drawing separately.';return {index,label:RECALL_LEVELS[index],next};}
function levelBadge(a){const l=aminoLevel(a);return `<span class="recallbadge level${l.index}">Level ${l.index}/4 · ${l.label}</span>`;}
function claimRecallLevel(a,before){const name=typeof a==='string'?a:a.name,l=aminoLevel(a),highest=Math.max(progress.recallMilestones[name]??0,before);progress.recallMilestones[name]=highest;if(l.index>highest){progress.recallMilestones[name]=l.index;save();return l.index>before?l:null;}save();return null;}
function levelDetails(a){expose(a,['name']);const l=aminoLevel(a);modal(`<h2>${a.name}</h2>${levelBadge(a)}<p>${l.next}</p><p class="caption">Recall level uses four objective skills. A current miss returns the affected skill to practice. Old streaks are retained, but old data never earns delayed checks retroactively. These are practice milestones—not a certified mastery score.</p><div class="levelskills">${Object.keys(SKILL_NAMES).map(k=>{const t=skill(a,k);return `<div><b>${SKILL_NAMES[k]}</b><span>${t.right} correct · ${t.wrong} misses · ${t.hinted} assisted${recallSkills.includes(k)?` · ${t.delayedSuccess} lifetime delayed checks · ${t.retainedChecks} since latest miss`:''}</span></div>`;}).join('')}</div>${classificationEvidence(a)}${fluencyDetails(a)}<p class="caption">Drawing is self-assessed; building supplies a scaffold. Neither substitutes for unaided name/code/structure recall. Hints do not advance independent recall levels.</p>`);}

function rewardState(){let discoveries=0,checks=0,recoveries=0,assembly=0,recognitions=0;for(const a of AMINO){if(choiceSkills.some(k=>skill(a,k).right>0))recognitions++;assembly+=skill(a,'forge').assemblyAward?1:0;if(recallSkills.some(k=>skill(a,k).right>0))discoveries++;for(const k of recallSkills){const t=skill(a,k);if(t.delayedSuccess)checks++;if(t.recovered)recoveries++;}}const xp=discoveries*5+checks*10+recoveries*5+assembly*2+recognitions*2;return {discoveries,checks,recoveries,assembly,recognitions,xp,level:1+Math.floor(xp/100)};}

function quizSkill(kind){return kind==='fromcode'?'name':kind;}
function save(){if(saveDepth)return;syncResponseTiming();if(!storageBlocked){try{localStorage.setItem('amino-lab-v1',JSON.stringify(progress));storageIssue='';}catch{storageIssue='Progress could not be saved in this browser. Export a backup from Progress before leaving.';}}storageNotice();stats();}function stats(){const active=namesExam||!!(round?.exam&&round.i<round.items.length);for(const id of ['#listbtn','#about','#studyTips'])$(id).hidden=active;$('#companionButton').disabled=active;const r=rewardState();const evo=evolutionStage(r.xp);const portrait=$('#companionButton');if(portrait.dataset?.evolution!==String(evo.index)){portrait.innerHTML=companionArt(evo.index);if(portrait.dataset)portrait.dataset.evolution=String(evo.index);}$('#guildRank').textContent=evo.name+' · Level '+r.level;$('#xpFill').style.width=(r.xp%100)+'%';if($('#xpTrack').setAttribute)$('#xpTrack').setAttribute('aria-valuenow',r.xp%100);$('#nextUnlock').textContent=r.xp+' XP · '+(evo.next?(evo.next.xp-r.xp)+' XP to '+evo.next.name:'Final form · Guild Master');if(document.documentElement)document.documentElement.dataset.companion=progress.companion||'apprentice';const n=AMINO.filter(a=>aminoLevel(a).index>=3).length;$('#mastered').innerHTML=n+'<span>/ 20</span>';$('#ring').style.background=`conic-gradient(var(--ink) ${n*5}%,#d4dbc8 0%)`;$('#streak').textContent=`Level ${rewardState().level} · ${rewardState().xp} quest XP`;}
const moleculeSizes={"D": [320.0, 284.0], "N": [320.0, 284.0], "S": [320.0, 236.0], "Q": [320.0, 342.0], "K": [320.0, 409.0], "M": [320.0, 352.0], "V": [320.0, 227.0], "E": [320.0, 342.0], "P": [320.0, 220.0], "R": [320.0, 457.0], "A": [320.0, 220.0], "W": [329.0, 346.0], "C": [320.0, 236.0], "Y": [320.0, 380.0], "G": [320.0, 220.0], "F": [320.0, 332.0], "I": [320.0, 284.0], "H": [320.0, 310.0], "L": [320.0, 284.0], "T": [320.0, 227.0]};
const img=(a,classified=false)=>`<div class="moleculeboard" role="img" aria-label="Complete molecular structure"><img class="structure" style="--native-width:${moleculeSizes[a.one][0]}px" src="structures/${classified?'classification/':''}${a.one}.svg" alt="${classified?'Amber highlights the classification clue: '+SHORT_CLASS[a.one]:'Chemical structure diagram to identify'}" draggable="false"></div>`;

const convention='<details class="notation-help"><summary>Drawing convention</summary><p class="caption notation">Neutral condensed structures; blue = shared backbone. Stereo wedges omitted for connectivity practice. In water near neutral pH, amino/carboxyl groups are usually ionized. Follow your teacher’s drawing convention.</p></details>';
function changeMode(m){if(typeof releaseFocusDraw==='function')releaseFocusDraw();if(classificationGame){classificationGame.destroy?.();classificationGame=null;}stopResponseTiming();if(mode==='quest'&&m!=='quest'&&questRun()&&!questRun().complete){questRun().paused=true;save();}namesExam=false;mode=m;round=null;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.mode===m));render();}document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>changeMode(b.dataset.mode));$('.brand').onclick=e=>{e.preventDefault();changeMode('learn');};
function render(){stats();if(mode==='quest')renderQuest();else if(mode==='basics')renderFoundations();else if(mode==='learn')learn();else if(mode==='draw')draw();else if(mode==='forge')renderForge();else if(mode==='classify')renderClassification();else if(mode==='focus')renderFocus();else if(mode==='families')families();else if(mode==='progress')dashboard();else setup();}
const ONE_CUES={A:null,R:'Sound cue: arginine begins with an R sound.',N:null,D:'Asp / D is an assigned pair; learn it together.',C:null,E:'Glu / E is an assigned pair; learn it together.',Q:'Gln / Q is an assigned pair; learn it together.',G:null,H:null,I:null,L:null,K:'Memory cue: L is leucine; lysine uses its neighbour K.',M:null,F:'Memory cue: PH in phenylalanine sounds like F.',P:null,S:null,T:null,W:'Shape cue: bulky two-ring tryptophan goes with W.',Y:null,V:null};
function highlightedName(a,code){let pos=0;const indices=[];for(const c of code.toLowerCase()){const found=a.name.toLowerCase().indexOf(c,pos);if(found<0)throw Error('Invalid spelling cue');indices.push(found);pos=found+1;}return [...a.name].map((c,i)=>indices.includes(i)?'<mark>'+c+'</mark>':c).join('');}
function letterCues(a){return `<div class="lettercues"><div><b>${a.three}</b><span>${highlightedName(a,a.three)}</span></div><div><b>${a.one}</b><span>${ONE_CUES[a.one]||highlightedName(a,a.one)}</span></div></div>`;}
function learn(){const a=deck[card%deck.length];stage.innerHTML=`<div class="panel learnpanel"><div class="learnhead"><div class="paneltop"><h2>Discover the structure.</h2><button class="btn light" id="homeBasics">Read the pieces</button><button class="btn accent" id="homeQuest">✦ ${questRun()&&!questRun().complete?'Resume quest':'Start quest'}</button><span class="caption">${card+1} / ${deck.length}</span></div><div class="controls"><select id="cardSelect" aria-label="Jump to amino acid"><option value="" selected disabled>Jump to…</option>${deck.map((x,i)=>({x,i})).sort((a,b)=>a.x.name.localeCompare(b.x.name)).map(({x,i})=>`<option value="${i}">${x.name}</option>`).join('')}</select><button class="textbtn" id="shuffle">Shuffle</button></div></div><div class="learnlayout">${img(a,revealed)}<div class="identity"><div class="identitycontent">${revealed?`<div class="big">${a.name}</div>${classificationBadges(a)}<p class="classclue" id="classClue"><span aria-hidden="true">■</span> ${SHORT_CLASS[a.one]}</p>${letterCues(a)}${comparisonPairs(a).length?'<button class="btn light" id="compareCard">Compare a similar structure ↔</button>':''}`:'<p class="eyebrow">EXAM SKILL • IDENTIFY</p><h3>Recognize the side chain?</h3><p class="caption">Say the full name and both codes.<br>Then check your answer.</p>'}<button class="btn light" id="flip">${revealed?'Hide identity':'Reveal identity + codes'}</button></div><div class="actions"><button class="btn light" id="prev">← Previous</button><button class="btn" id="next">Next →</button></div><button class="btn accent" id="drawthis">Draw this one</button></div></div>${convention}</div>`;if(revealed){if(comparisonPairs(a).length)$('#compareCard').onclick=()=>compareCard(a);$('#classificationHelp').onclick=()=>classificationHelp(a.one);document.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>groupHelp(a,b.dataset.group));const picture=$('.learnpanel .structure');picture.onerror=()=>{picture.onerror=null;picture.src='structures/'+a.one+'.svg';$('#classClue').textContent='Side-chain clue: '+SHORT_CLASS[a.one];};}$('#homeBasics').onclick=()=>changeMode('basics');$('#homeQuest').onclick=()=>{if(questRun()&&!questRun().complete){questRun().paused=false;save();changeMode('quest');}else startQuest();};$('#flip').onclick=()=>{revealed=!revealed;if(revealed)expose(a);learn();$('#flip').focus?.();};$('#next').onclick=()=>{card=(card+1)%deck.length;revealed=false;learn();};$('#prev').onclick=()=>{card=(card+deck.length-1)%deck.length;revealed=false;learn();};$('#cardSelect').onfocus=()=>deck.forEach(a=>expose(a,['name']));$('#cardSelect').onchange=e=>{if(e.target.value==='')return;card=+e.target.value;revealed=false;expose(deck[card]);learn();};$('#shuffle').onclick=()=>{deck=shuffle(deck);card=0;revealed=false;learn();};$('#drawthis').onclick=()=>{drawName=a.name;drawScaffold=true;drawAssisted=true;drawShown=false;paths=[];changeMode('draw');};}
function backboneScaffold(a){return `<svg class="backbone-scaffold" viewBox="0 -40 1100 640" preserveAspectRatio="xMidYMin meet" role="img" aria-label="Shared backbone supplied; draw only the side chain from the downward bond${a.one==='P'?'; close the side chain back to nitrogen':''}"><g stroke="#52657d" stroke-width="4" stroke-linecap="round" fill="none"><path d="M350 120H508 M586 120H738 M822 120H956 M550 83V23 M550 151V205 M770 82V23 M786 82V23${a.one==='P'?' M316 151V205':''}"/></g><g fill="#34465f" font-family="Arial,Helvetica,sans-serif" font-size="44" text-anchor="middle">${a.one==='P'?'<text x="276" y="137">H</text><text x="316" y="137">N</text>':'<text x="330" y="137" text-anchor="end">H<tspan baseline-shift="sub" font-size="28">2</tspan>N</text>'}<text x="550" y="137">C</text><text x="780" y="137">C</text><text x="1000" y="137">OH</text><text x="550" y="9">H</text><text x="780" y="9">O</text></g>${a.one==='P'?'<text x="550" y="560" fill="#5b6575" font-size="35" text-anchor="middle">Close the side chain back to N.</text>':''}</svg>`;}
function draw(){const a=AMINO.find(a=>a.name===drawName);expose(a,['name']);stage.innerHTML=`<div class="panel drawpanel"><div class="paneltop"><h2>Sketch your discovery.</h2><div class="row"><button class="btn light" id="openForge">Molecule Forge</button><span class="tag">SELF-CHECK</span></div></div><div class="controls"><label for="drawSelect" class="caption">Amino acid</label><select id="drawSelect">${AMINO.map(x=>`<option ${x.name===drawName?'selected':''}>${x.name}</option>`).join('')}</select><button class="textbtn" id="randomDraw">Surprise me</button></div><p class="caption">${drawScaffold?'Side-chain drawing · backbone supplied.':'Full-structure drawing · blank canvas.'} Paper works too.</p><div class="drawlayout ${drawShown?'comparing':''}"><div class="sketchside"><div class="canvaswrap"><div class="drawing-surface${drawScaffold?' scaffolded':''}">${drawScaffold?backboneScaffold(a):''}<canvas id="pad" width="1100" height="600" aria-label="Freehand structure drawing area"></canvas></div><span class="canvaslabel">YOUR SKETCH</span></div><div class="row drawtools"><button class="btn light" id="scaffoldToggle">Side-chain practice</button><button class="btn light" id="blankTry">Full structure</button><button class="btn light" id="undo">Undo stroke</button><button class="btn light" id="clear">Clear sketch</button><button class="btn light" id="earlyReference">Need a reference</button><button class="btn" id="revealDraw">${drawShown?'Hide reference':'Finish drawing & compare'}</button></div></div><div id="reference" ${drawShown?'':'hidden'}>${img(a)}<div class="row"><b>${a.name}</b><span class="tag">${a.three} · ${a.one}</span></div><p class="caption">Check bonds, CH₂ count, branches/rings, N/O/S and the backbone. ${drawScaffold?'Backbone supplied: self-rate the side chain.':drawAssisted?'Assisted full-structure attempt.':'Blank-start full-structure attempt.'} Self-rated, not automatically graded.</p><div class="actions"><button class="btn light" id="againDraw">Needs another try</button><button class="btn accent" id="gotDraw">Looks right → next</button></div></div></div>${convention}</div>`;$('#openForge').onclick=()=>changeMode('forge');$('#scaffoldToggle').onclick=()=>{drawScaffold=true;drawAssisted=true;draw();};$('#blankTry').onclick=()=>{drawScaffold=false;drawAssisted=false;drawShown=false;paths=[];draw();};$('#drawSelect').onchange=e=>{drawName=e.target.value;drawScaffold=true;drawAssisted=true;paths=[];drawShown=false;draw();};$('#randomDraw').onclick=()=>{drawName=shuffle(AMINO)[0].name;drawScaffold=true;drawAssisted=true;paths=[];drawShown=false;draw();};$('#revealDraw').onclick=()=>{drawShown=!drawShown;if(drawShown)expose(a);draw();};$('#againDraw').onclick=()=>{if(!progress.missed.includes(a.name))progress.missed.push(a.name);record(a,'draw',false,{hinted:drawAssisted});save();paths=[];drawShown=false;draw();};$('#gotDraw').onclick=()=>{record(a,'draw',true,{hinted:drawAssisted});drawName=AMINO[(AMINO.indexOf(a)+1)%20].name;drawScaffold=false;drawAssisted=false;paths=[];drawShown=false;draw();};const canvas=$('#pad'),ctx=canvas.getContext('2d');function paint(){ctx.clearRect(0,0,canvas.width,canvas.height);ctx.strokeStyle='#163e3a';ctx.lineWidth=4;ctx.lineCap='round';ctx.lineJoin='round';for(const path of paths){ctx.beginPath();path.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.stroke();}}function pt(e){const r=canvas.getBoundingClientRect();return[(e.clientX-r.left)*canvas.width/r.width,(e.clientY-r.top)*canvas.height/r.height];}canvas.onpointerdown=e=>{e.preventDefault();drawing=true;canvas.setPointerCapture(e.pointerId);paths.push([pt(e)]);};canvas.onpointermove=e=>{if(drawing){paths.at(-1).push(pt(e));paint();}};canvas.onpointerup=canvas.onpointercancel=()=>{drawing=false;};$('#undo').onclick=()=>{paths.pop();paint();};$('#clear').onclick=()=>{paths=[];paint();};paint();if(isQuestTask('draw'))bindQuestDraw();else bindStandaloneDraw();if(round?.focus&&round.items[round.i]?.kind==='draw')bindFocusDraw();$('#scaffoldToggle').setAttribute?.('aria-pressed',String(drawScaffold));$('#blankTry').setAttribute?.('aria-pressed',String(!drawScaffold));}
const PRACTICE_TOPICS=[['mixed','Mixed recall'],['structure','Structure → name'],['three','Name → 3-letter'],['one','Name → 1-letter'],['fromcode','Codes → name'],['contrast','Spot differences']];
function chooseTopic(value){if(!PRACTICE_TOPICS.some(t=>t[0]===value))return;topic=value;setup();$('#topic-'+value).focus();}
function setup(){namesExam=false;stats();const exam=mode==='exam';stage.innerHTML=`<div class="panel"><p class="eyebrow">${exam?'THE DRESS REHEARSAL':'LOW PRESSURE. LOTS OF PRACTICE.'}</p><h2>${exam?'Boss round: the 20-question challenge.':'Train your recall.'}</h2><p class="caption">${exam?'20 questions; mixed mode covers all 20 amino acids. Contrasts revisit structural pairs. Feedback at the end. No timer.':'Answer 10 questions. Get feedback after each, then review what needs another look.'}</p><p class="label" id="topicLabel">Choose your practice</p><div class="topicchoices" role="group" aria-labelledby="topicLabel">${PRACTICE_TOPICS.map(([value,label])=>`<button class="btn light ${topic===value?'selected':''}" id="topic-${value}" data-topic="${value}" aria-pressed="${topic===value}">${label}</button>`).join('')}</div>${!exam&&topic!=='contrast'?`<div class="answerformats setupformats" role="group" aria-label="Answer format"><button class="btn light ${progress.practiceFormat==='choice'?'selected':''}" id="chooseMC" aria-pressed="${progress.practiceFormat==='choice'}">Adaptive practice</button><button class="btn light ${progress.practiceFormat==='typed'?'selected':''}" id="chooseTyped" aria-pressed="${progress.practiceFormat==='typed'}">Hard mode · type</button></div>`:''}<div class="actions"><button class="btn" id="start">${exam?'Start mock exam':'Start 10 questions'} →</button>${!exam?`<button class="btn accent" id="shortQuest">Start adaptive quest</button><button class="btn light" id="dueNow">Due now (${dueItems().length})</button><button class="btn light" id="misses" ${!progress.missed.length?'disabled':''}>Review misses (${progress.missed.length})</button>`:''}<button class="btn light" id="fullrecall">Recall all 20 names →</button></div><p class="caption">${exam?'No choices or hints: type each answer from memory.':'Adaptive starts with 4 choices, then uses typing when your recent answers support it. Hard mode always uses typing.'}</p></div>`;document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>chooseTopic(b.dataset.topic));if(!exam&&topic!=='contrast'){$('#chooseMC').onclick=()=>choosePracticeFormat('choice');$('#chooseTyped').onclick=()=>choosePracticeFormat('typed');}$('#start').onclick=()=>{if(topic==='names'){startRecall(exam);return;}startRound(exam,false);};$('#fullrecall').onclick=()=>startRecall(exam);if(!exam){$('#shortQuest').onclick=()=>changeMode('quest');$('#dueNow').onclick=startDue;}if($('#misses'))$('#misses').onclick=()=>startRound(false,true);}
function startRound(exam,missed,count=10){if(topic==='names'){startRecall(exam);return;}if(topic==='contrast'){const qs=shuffle(exam?[...CONTRASTS,...CONTRASTS.slice(0,8)]:CONTRASTS).slice(0,exam?20:count).map(c=>({a:AMINO.find(a=>a.one===c.target),kind:'contrast',contrast:c}));round={exam,items:qs,i:0,answers:[],locked:false,confidence:null};progress.practiceFormat='choice';save();question();return;}const pool=missed?AMINO.filter(a=>progress.missed.includes(a.name)):AMINO;const selected=shuffle(pool).sort((a,b)=>exam?0:Math.min(...['structure','name','three','one'].map(k=>skill(a,practiceSkill(k==='name'?'fromcode':k,progress.practiceFormat)).streak))-Math.min(...['structure','name','three','one'].map(k=>skill(b,practiceSkill(k==='name'?'fromcode':k,progress.practiceFormat)).streak))).slice(0,exam?20:count);round={exam,items:selected.map((a,i)=>({a,kind:(topic==='mixed'||missed)?(exam?['structure','three','one','fromcode'][i%4]:shuffle(['structure','three','one','fromcode']).sort((x,y)=>weakScore(a,practiceSkill(x,progress.practiceFormat))-weakScore(a,practiceSkill(y,progress.practiceFormat)))[0]):topic})),i:0,answers:[],locked:false,hardOverride:!exam&&progress.practiceFormat==='typed',format:progress.practiceFormat==='typed'?'typed':null};progress.practiceFormat='choice';save();question();}
function question(reformat=false){stats();if(!round.rewardStart)round.rewardStart=rewardState();const q=round.items[round.i];q.resumeTiming=round.quest?!!(questRun().current.answerFormat||questRun().current.choiceViewed||questRun().current.input):false;round.locked=round.quest?questRun().current.answered:false;round.confidence=null;q.assisted=round.quest?questRun().current.assisted:(reformat?!!q.assisted:false);q.hintStage=round.quest?questRun().current.hintStage:(reformat?q.hintStage:0);prepareAnswerFormat(q);if(q.kind==='three'||q.kind==='one')expose(q.a,['name']);if(q.kind==='fromcode')expose(q.a,['three','one']);const prompt=q.kind==='contrast'?q.contrast.prompt:q.kind==='structure'?'Which amino acid is this?':q.kind==='three'?`What is the 3-letter code for ${q.a.name}?`:q.kind==='one'?`What is the 1-letter code for ${q.a.name}?`:`What is the full name for <span class="code-label">${q.a.three} (${q.a.one})</span>?`;stage.innerHTML=`<div class="panel questionpanel"><div class="paneltop"><span class="eyebrow">${round.exam?'MOCK EXAM':round.focus?'FOCUS PRACTICE':'QUICK QUIZ'}</span><span class="caption">${round.i+1} / ${round.items.length}</span></div><div class="bar"><span style="width:${round.i/round.items.length*100}%"></span></div><div class="questionlayout ${q.kind==='structure'?'withstructure':''}">${q.kind==='structure'?img(q.a):''}<div class="questionentry"><h2 class="question">${prompt}</h2>${answerControls(q)}${q.difficulty&&!round.quest&&!round.exam?`<details class="adaptivewhy answerstyle"><summary>${q.answerFormat==='choice'?'4 choices':'Hard mode'} · Why this format?</summary><small>${window.AminoQuestEngine.reasonText({kind:q.kind,answerFormat:q.answerFormat,reasonKey:q.difficulty.reasonKey})}</small></details>`:''}<div id="feedback"></div>${!round.exam?'<div class="hintbar"><button class="textbtn" id="hintButton">Try first · Hint if stuck</button><button class="textbtn" id="assistedNext" hidden>Use help & continue →</button></div><div id="hintText" class="hinttext" aria-live="polite"></div>':''}<div class="actions"><button class="textbtn" id="skip">I’m not sure</button><button class="btn" id="continue" hidden>Next →</button></div><button class="textbtn" id="exitRound">End round</button></div></div></div>`;if(!round.exam){$('#hintButton').onclick=showHint;$('#assistedNext').onclick=()=>{if(round.locked)return;answer(expected(q));nextQuestion();};}bindAnswerControls(q);$('#answerForm').onsubmit=e=>{e.preventDefault();answer($('#answer').value);};$('#skip').onclick=()=>{round.confidence=null;answer('');};$('#continue').onclick=nextQuestion;$('#exitRound').onclick=()=>{stopResponseTiming();round=null;setup();};if(q.answerFormat==='typed')$('#answer').focus();if(round.quest)bindQuestQuestion();if(round.focus)focusFrame();startResponseTiming(q,reformat);}
function expected(q){return q.kind==='three'?q.a.three:q.kind==='one'?q.a.one:q.a.name;}
function correct(q,v){return ['one','three'].includes(q.kind)?v.trim().toLowerCase()===expected(q).toLowerCase():findAmino(v)?.name===q.a.name;}
function answer(v){if(round.locked)return;return atomicProgress(()=>{round.locked=true;const q=round.items[round.i],ok=correct(q,v);const levelBefore=aminoLevel(q.a).index;const before=rewardState().xp;const recognition=q.answerFormat==='choice';finishResponseTiming(q,ok);const review=record(q.a,practiceSkill(q.kind,q.answerFormat),ok,{confidence:null,hinted:q.assisted,retentionEligible:!recognition});progress.lastAnswerFormat=recognition?'choice':'typed';dashboardView=null;const gained=rewardState().xp-before;const levelUp=!recognition&&recallSkills.includes(quizSkill(q.kind))&&!q.assisted?claimRecallLevel(q.a,levelBefore):null;round.answers.push({q,given:v,ok,confidence:round.confidence,assisted:q.assisted,recognition,delayed:review.delayed,gained,levelUp});if((!ok||q.assisted)&&!round.exam&&!round.quest&&!round.focus&&!q.retry&&round.items.length<14&&round.items.length-round.i-1>=3){round.items.splice(round.i+4,0,{...q,retry:true,answerFormat:null,optionIds:[],choiceViewed:false});}progress.attempts++;if(ok){progress.right++;if(!progress.correct.includes(q.a.name))progress.correct.push(q.a.name);if([...recallSkills,...choiceSkills,'draw'].every(k=>{const t=skill(q.a,k);return !(t.wrong&&t.streak===0);}))progress.missed=progress.missed.filter(n=>n!==q.a.name);}else if(!progress.missed.includes(q.a.name))progress.missed.push(q.a.name);save();if(round.quest)questRecordRecall(q,v,ok,review,gained);if(round.focus)recordFocusOutcome(q,ok);if(round.exam){nextQuestion();return;}expose(q.a);const selected=q.options?.find(o=>o.label===v);if(selected&&selected.id!==q.a.one)expose(AMINO.find(a=>a.one===selected.id));lockAnswerControls(q);$('#answer').disabled=true;$('#check').disabled=true;$('#skip').hidden=true;$('#feedback').innerHTML=`<div class="feedback ${ok?'':'wrong'}">${ok?(recognition?'✓ Correct choice.':'✓ Correct. Nice recall!'):`Not yet. The answer is <b class="${['one','three'].includes(q.kind)?'code-label':''}">${expected(q)}</b>.`}<br><span class="caption">${q.a.name} · <span class="code-label">${q.a.three} · ${q.a.one}</span>${codeLookalikeHelp(q,v,ok)}${selected?'<br>'+selected.feedback:''}${q.contrast?'<br>'+q.contrast.reason:''}<br>${q.assisted?'Assisted practice—not independent recall credit.':recognition?'Choice recognition recorded separately from typed recall.':review.delayed?'✓ Delayed recall check passed.':'Unaided practice. Delayed recall is tracked separately.'}${gained?' ✦ +'+gained+' quest XP':''}${levelUp?'<br>✦ Recall level up: '+levelUp.label+'!':''}${q.contrast?'<br>Explain aloud: which atom, bond, or branch changed?':''}</span></div>`;$('#continue').hidden=false;$('#continue').focus();});}
function nextQuestion(){if(round?.focus){focusNext();return;}stopResponseTiming();if(!round||round.i>=round.items.length)return;if(round.quest){advanceQuest();return;}round.i++;if(round.i>=round.items.length)results();else question();}
function results(){stats();const r=rewardState(),before=round.rewardStart||r;const evolved=evolutionStage(r.xp).index>evolutionStage(before.xp??r.xp).index&&!round.evolutionCelebrated;if(evolved)round.evolutionCelebrated=true;const unlocked=before.discoveries<5&&r.discoveries>=5?'Sage color palette unlocked!':before.checks<5&&r.checks>=5?'Starlight color palette unlocked!':'';const levelUps=round.answers.filter(x=>x.levelUp);const typed=round.answers.filter(x=>!x.recognition),choices=round.answers.filter(x=>x.recognition);const n=round.answers.filter(x=>x.ok&&!x.assisted).length;const misses=round.answers.filter(x=>!x.ok);for(const x of misses)expose(x.q.a);stage.innerHTML=`<div class="panel"><p class="eyebrow">${round.exam?'MOCK EXAM COMPLETE':'PRACTICE COMPLETE'}</p><div class="questreward ${evolved?'evolution-burst':''}"><span class="rewardportrait">${companionArt(evolutionStage(r.xp).index)}</span><div><b>+${round.answers.reduce((n,x)=>n+(x.gained||0),0)} quest XP</b><small>${evolved?'EVOLVED! Your companion is now '+evolutionStage(r.xp).name+'.':unlocked||'Every honest attempt helps find your next practice target.'}</small></div><button class="btn light" id="questCollection">Your companion →</button></div>${levelUps.length?`<p class="caption levelround">✦ Recall level-ups: ${levelUps.slice(0,3).map(x=>x.q.a.name+' → '+x.levelUp.label).join(' · ')}${levelUps.length>3?' · +'+(levelUps.length-3)+' more':''}</p>`:''}<h2>${n===round.items.length?'That’s a clean sweep.':'Every miss is a next step.'}</h2><p class="caption">${round.answers.filter(x=>x.assisted).length} assisted · ${round.answers.filter(x=>x.delayed).length} delayed checks · ${round.answers.reduce((n,x)=>n+(x.gained||0),0)} earned quest XP. Mistakes guide your next practice—not a penalty.</p><div class="score">${n}<span style="font-size:25px;color:var(--muted)"> / ${round.items.length} correct without hints</span></div><p class="caption">${choices.filter(x=>x.ok&&!x.assisted).length}/${choices.length} choice recognition · ${typed.filter(x=>x.ok&&!x.assisted).length}/${typed.length} typed recall</p><p class="caption">${misses.length?'Revisit these, then try again.':'Try a different question type, then draw the structures from memory.'}</p><details class="roundreview"><summary>Review answers (${misses.length} misses)</summary>${misses.map(x=>`<div class="reviewrow"><b>${x.q.a.name}</b> · ${x.q.a.three} · ${x.q.a.one}<br>Expected ${x.q.kind==='three'?'3-letter code':x.q.kind==='one'?'1-letter code':'full name'}: <b>${expected(x.q)}</b>${x.q.contrast?'<br>'+x.q.contrast.reason:''}</div>`).join('')}</details><p class="caption">Take a short break, then return to Due now. If none are due, switch skills or draw on paper. Rest and sleep matter too.</p><div class="actions"><button class="btn" id="restart">Another round</button><button class="btn light" id="practiceMisses" ${!misses.length?'disabled':''}>Mix in weak spots</button><button class="textbtn" id="learnAgain">Back to cards</button></div></div>`;$('#questCollection').onclick=showRewards;$('#restart').onclick=()=>{round=null;setup();};$('#practiceMisses').onclick=()=>{topic='mixed';startRound(false,false,10);};$('#learnAgain').onclick=()=>changeMode('learn');}
function startRecall(exam){progress.practiceFormat='choice';namesExam=exam;stats();let found=[],hints=false,done=false;function show(){stage.innerHTML=`<div class="panel"><div class="paneltop"><h2>Recall all 20 names.</h2><span class="tag">${found.length} / 20</span></div><p class="caption">Any order. No codes needed. Try without hints first.</p><form id="recallForm"><div class="inputrow"><input id="recallInput" aria-label="Amino acid name" placeholder="Type an amino acid name" autocomplete="off" spellcheck="false"><button class="btn">Add name</button></div></form><div id="recallFeedback"></div><div class="namegrid">${AMINO.map((a,i)=>`<div class="namechip ${found.includes(a.name)?'':'empty'}"><b>${String(i+1).padStart(2,'0')}</b>${found.includes(a.name)?a.name:done?a.name:hints?a.name[0]+'…':'—'}</div>`).join('')}</div><div class="actions">${!exam?'<button class="btn light" id="hintNames">Show first-letter hints</button>':''}<button class="btn" id="finishNames">${done?'Try again':'Finish & reveal missing'}</button></div><button class="textbtn" id="backNames">Back</button></div>`;$('#recallForm').onsubmit=e=>{e.preventDefault();if(done)return;const value=$('#recallInput').value,a=findAmino(value);if(!a){$('#recallFeedback').innerHTML='<div class="feedback wrong">That doesn’t match a standard name yet. Check the spelling and try again.</div>';return;}if(found.includes(a.name)){$('#recallFeedback').innerHTML='<div class="feedback">You already have that one. Try another.</div>';return;}found.push(a.name);record(a,'name',true,{hinted:hints,retentionEligible:false});show();$('#recallInput').focus();if(found.length===20){$('#recallFeedback').innerHTML='<div class="feedback">✓ All twenty! Now test the structures and codes.</div>';}};if($('#hintNames'))$('#hintNames').onclick=()=>{atomicProgress(()=>{if(!hints)AMINO.filter(a=>!found.includes(a.name)).forEach(a=>{noteResponseSupport({a,kind:'fromcode',answerFormat:'typed'});if(progress.focusState)invalidateFocusEvidence(a.one,'name');});hints=true;AMINO.forEach(a=>expose(a,['name']));});show();};$('#finishNames').onclick=()=>{if(done){startRecall(exam);return;}done=true;namesExam=false;for(const a of AMINO.filter(a=>!found.includes(a.name))){if(!progress.missed.includes(a.name))progress.missed.push(a.name);if(!hints)record(a,'name',false);}save();show();$('#recallInput').disabled=true;};$('#backNames').onclick=setup;}show();}
const HINT_FEATURES={A:'A single CH₃ side chain.',R:'A long chain ending in a group with three nitrogens.',N:'One CH₂, then an amide: C(=O)NH₂.',D:'One CH₂, then a carboxyl group: COOH.',C:'A CH₂ ending in SH, not OH.',E:'Two CH₂ groups, then COOH.',Q:'Two CH₂ groups, then C(=O)NH₂.',G:'The side chain is just H.',H:'A five-membered aromatic ring with two nitrogens.',I:'The first side-chain carbon is the branch point; one arm is CH₃, one is CH₂CH₃.',L:'One CH₂ before the fork into two CH₃ groups.',K:'Four CH₂ groups, then NH₂.',M:'Two CH₂ groups, then S–CH₃.',F:'CH₂ attached to a six-membered carbon ring, with no ring OH.',P:'The side chain loops back to the backbone nitrogen.',S:'One CH₂ ending in OH, not SH.',T:'A side-chain carbon carries both OH and CH₃.',W:'Two fused aromatic rings, including one NH.',Y:'CH₂ attached to an aromatic ring with an OH opposite the attachment.',V:'The first side-chain carbon forks into two CH₃ groups.'};
function showHint(){if(!round||round.exam||round.locked)return;const q=round.items[round.i];if(!q.assisted)noteResponseSupport(q);q.assisted=true;if(round.quest)questRun().current.assisted=true;q.hintStage++;expose(q.a);let text;
 if(q.hintStage===1)text='Feature clue: '+HINT_FEATURES[q.a.one]+(q.kind==='one'||q.kind==='three'?' Say the name and its abbreviation pair aloud.':'');
 else if(q.kind==='one'||q.hintStage>=3){q.hintStage=3;text='Answer: '+expected(q)+'. '+q.a.name+' · '+q.a.three+' · '+q.a.one+'. '+(q.contrast?q.contrast.reason:HINT_FEATURES[q.a.one]);$('#hintButton').hidden=true;$('#assistedNext').hidden=false;}
 else text='Partial '+(q.kind==='three'?'code':'name')+': '+expected(q).slice(0,q.kind==='three'?1:2)+'…';
 $('#hintText').textContent=text+' Assisted practice: return later without hints for independent credit.';if(q.hintStage<3)$('#hintButton').textContent='Next hint →';if(round.quest)questSyncQuestion();}
const CONTRASTS=[
{target:'C',prompt:'Start with serine. Replace its side-chain –OH with –SH. Which amino acid results?',reason:'Cysteine has CH₂–SH; serine has CH₂–OH. Oxygen becomes sulfur.'},
{target:'T',prompt:'Start with serine, CH₂OH. Add CH₃ to that side-chain carbon, replacing one H. Which amino acid results?',reason:'Threonine has CH(OH)–CH₃, compared with serine’s CH₂–OH.'},
{target:'E',prompt:'Aspartic acid has CH₂–COOH. Insert one extra CH₂ before COOH. Which amino acid results?',reason:'Glutamic acid has CH₂–CH₂–COOH: one extra methylene group.'},
{target:'Q',prompt:'Asparagine has CH₂–CONH₂. Insert one extra CH₂ before CONH₂. Which amino acid results?',reason:'Glutamine has CH₂–CH₂–CONH₂, one CH₂ longer than asparagine.'},
{target:'N',prompt:'Replace the side-chain –OH of aspartic acid’s –COOH with –NH₂. Which amino acid results?',reason:'Asparagine is the matching amide: CH₂–CONH₂. The C=O stays.'},
{target:'Q',prompt:'Replace the side-chain –OH of glutamic acid’s –COOH with –NH₂. Which amino acid results?',reason:'Glutamine is the matching amide: CH₂–CH₂–CONH₂. The C=O stays.'},
{target:'Y',prompt:'Which amino acid is phenylalanine with an –OH added opposite the side-chain attachment on its benzene ring?',reason:'Tyrosine has a para –OH on phenylalanine’s six-membered aromatic ring.'},
{target:'I',prompt:'Leucine is CH₂–CH(CH₃)₂. Which isomer branches at the first side-chain carbon instead: CH(CH₃)–CH₂–CH₃?',reason:'Isoleucine has the same formula as leucine, but its branch is closer to the backbone.'},
{target:'P',prompt:'Which standard amino acid loops its three-CH₂ side chain back to its own backbone nitrogen?',reason:'Proline closes a five-membered ring including the nitrogen and α-carbon. Its neutral amino group is HN, not H₂N.'},
{target:'G',prompt:'Alanine has CH₃ as R. Replace that entire R group with H. Which amino acid results?',reason:'Glycine has H as R, so the α-carbon has two hydrogens.'},
{target:'F',prompt:'Tyrosine has a benzene-ring –OH. Replace that –OH with H. Which amino acid results?',reason:'Phenylalanine has the same CH₂–phenyl side chain without tyrosine’s ring hydroxyl.'},
{target:'S',prompt:'Cysteine ends in –SH. Replace S with O, keeping H. Which amino acid results?',reason:'Serine ends in –OH; cysteine ends in –SH.'}
];
function startDue(){const items=shuffle(dueItems()).sort((x,y)=>weakScore(x.a,quizSkill(x.kind))-weakScore(y.a,quizSkill(y.kind))).slice(0,10);if(!items.length){modal('<h2>No delayed reviews due yet.</h2><p>Delayed checks need time away from the answer. Recent mistakes also need three intervening other-item questions; a long break can stand alone. Try a different skill, draw on paper, or take a break. No waiting is required.</p><p>The 2-minute, 10-minute and next-day intervals are practical app rules, not a proven optimal schedule or exam prediction.</p>');return;}round={exam:false,format:'typed',items,i:0,answers:[],locked:false,confidence:null};question();}
function showRewards(){referenceAssistance();const r=rewardState();AMINO.filter(a=>[...recallSkills,...choiceSkills].some(k=>skill(a,k).right>0)).forEach(a=>expose(a,['name']));modal(`<h2>Amino Guild · Your evolving companion</h2>${evolutionPanel(r)}<p>Level ${r.level} · ${r.xp} quest XP. Levels celebrate practice milestones, not exam readiness.</p><p>✦ ${r.discoveries}/20 discovered by typed recall · ${r.recognitions}/20 recognized with choices<br>◈ ${r.checks}/80 skills with a delayed check<br>◆ ${r.recoveries} skills recovered after a miss and a delay</p><p>Each milestone rewards once: discovery +5, first delayed check +10, first delayed recovery +5. Clean first-check challenge assembly +2 once per amino acid (${r.assembly}/20 earned); assembly XP is cosmetic, not recall credit. First correct recognition with choices earns +2 once per amino acid, separately from recall. No speed bonus; mistakes cost nothing.</p><p class="caption">Optional color palettes (your evolved form stays):</p><div class="row companionchoices"><button class="btn light" id="compApprentice">Apprentice</button><button class="btn light" id="compSage" ${r.discoveries<5?'disabled':''}>Sage · 5 discoveries</button><button class="btn light" id="compStar" ${r.checks<5?'disabled':''}>Starlight · 5 delayed skills</button></div><div class="namegrid">${AMINO.map(a=>`<div class="namechip">${[...recallSkills,...choiceSkills].some(k=>skill(a,k).right>0)?'✦ '+a.name:'◇ Undiscovered'}<small>${levelBadge(a)}</small></div>`).join('')}</div>`);$('#compApprentice').onclick=()=>chooseCompanion('apprentice');$('#compSage').onclick=()=>chooseCompanion('sage');$('#compStar').onclick=()=>chooseCompanion('starlight');}
function chooseCompanion(name){const r=rewardState();if(name==='sage'&&r.discoveries<5||name==='starlight'&&r.checks<5)return;progress.companion=name;save();$('#dialog').close();}
function studyIdeas(){referenceAssistance();for(const code of ['H','W','P','C','M','K','R','F','L','Y','N','D','E','Q'])expose(AMINO.find(a=>a.one===code));modal(`<h2>Study ideas & memory tools</h2><p>Try recalling first. Use these clues to notice the structure, then close this reference and retrieve it again later.</p><details open><summary>Ring detective</summary><p>Count rings and nitrogen atoms. Histidine: one five-membered ring, two N. Tryptophan: fused five- and six-membered rings, one N. Proline: a five-membered loop returns to the backbone N, with three CH₂ groups in the side-chain loop. Imidazole in histidine is aromatic too.</p></details><details><summary>Sulfur: tip or middle?</summary><p>Cysteine ends in CH₂–SH; methionine continues past sulfur: CH₂–CH₂–S–CH₃. Memory cue: “Cys ends in SH; Met carries on past S.” This is a structural cue, not a name origin.</p></details><details><summary>Nitrogen landmarks</summary><p>Lysine: four CH₂ groups, then NH₂. Histidine: a ring containing two N. Arginine: three CH₂ groups, then NH–C(=NH)–NH₂, a three-nitrogen end group. These match the neutral classroom drawings; not every NH₂ is basic—amide groups in Asn/Gln differ.</p></details><details><summary>One-letter sound & shape cues</summary><p>IUPAC explains F with the “phenyl” F sound, R with the initial sound in arginine, and W with bulky two-ring tryptophan. Learner cue: L belongs to leucine; lysine uses its alphabet neighbour K. Other spelling highlights are memory aids, not claims about historical assignment.</p></details><details><summary>Three-letter look-alikes</summary><p>Asp = aspartic acid; Asn = asparagine. Glu = glutamic acid; Gln = glutamine. Trp = tryptophan; Tyr = tyrosine. Compare each pair aloud, then cover the codes and produce both from memory.</p></details><details><summary>Cover → draw → check → revisit</summary><p>Start from a name or code. Cover the answer, draw the shared backbone, then add the side chain. Check CH₂ count, branch position, N/O/S placement and rings. Try again later without looking. Paper works as well as the drawing pad. Classroom research supports trying drawing-from-memory activities; it does not prove these particular cues or predict tomorrow’s exam score.</p></details><h3>Sources</h3><p class="caption"><a href="https://iupac.qmul.ac.uk/AminoAcid/A2021.html" target="_blank" rel="noopener">IUPAC: amino-acid symbols</a><br><a href="https://openstax.org/books/organic-chemistry/pages/26-1-structures-of-amino-acids" target="_blank" rel="noopener">OpenStax: amino-acid structures</a><br><a href="https://www.chem.ucalgary.ca/courses/350/Carey5th/Ch27/ch27-p-ans.html" target="_blank" rel="noopener">University of Calgary: sulfur groups</a><br><a href="https://pubmed.ncbi.nlm.nih.gov/25345852/" target="_blank" rel="noopener">Amino-acid drawing and code-learning classroom study</a></p>`);}

$('#studyTips').onclick=studyIdeas;$('#companionButton').onclick=showRewards;
function modal(html){$('#dialogcontent').innerHTML=html;$('#dialog').showModal();}$('#close').onclick=()=>$('#dialog').close();$('#listbtn').onclick=()=>{referenceAssistance();AMINO.forEach(a=>expose(a,['name','three','one']));modal(`<h2>The correct 20</h2><p>Your original list contained spelling errors and duplicates. Arginine, histidine and lysine were missing. “Base” is a category, not an amino-acid name.</p><div class="namegrid">${AMINO.map(a=>`<div class="namechip">${a.name}<span class="mini">${a.three} · ${a.one}</span></div>`).join('')}</div>`)};$('#about').onclick=()=>{referenceAssistance();modal(`<h2>Study the right things.</h2><p>Try: retrieve → check → explain the difference → return later. Explain an atom/bond/branch change aloud, then compare with the model explanation; the app does not grade speech.</p><p><a href="https://pubmed.ncbi.nlm.nih.gov/16507066/" target="_blank" rel="noopener">Roediger & Karpicke: retrieval practice</a><br><a href="https://pubmed.ncbi.nlm.nih.gov/19076480/" target="_blank" rel="noopener">Cepeda and colleagues: spacing and retention intervals</a><br><a href="https://pubmed.ncbi.nlm.nih.gov/18605878/" target="_blank" rel="noopener">Butler and colleagues: confidence and feedback</a><br><a href="https://pubmed.ncbi.nlm.nih.gov/18578849/" target="_blank" rel="noopener">Kornell &amp; Bjork: interleaved category learning</a></p><p>These findings support learning principles, not a clinical or exam-validation claim for this app. Interleaved contrast practice and exact scheduling here are practical design choices. Review again before the exam even if a next-day review is not yet due; early practice is welcome.</p><p>This app covers the 20 standard protein amino acids, their structures, names and codes. It is not an official Cambridge resource or a guarantee of your teacher’s exam coverage.</p><p>Neutral forms are used consistently. In water near neutral pH, the amino and carboxyl groups are predominantly charged (zwitterionic). Side chains may also be charged. Follow your class’s conventions for charge, displayed/skeletal formulae and stereochemistry.</p><p>Sketches are self-assessed, not machine-graded. Practice streaks and delayed recall are separate. A delayed check requires an unaided first answer, a due item and at least two minutes without seeing its answer. A recent wrong-answer retry also needs three intervening other-item questions; a delay of six hours or more can stand alone. The 2-minute, 10-minute and next-day schedule is an app heuristic, not a validated optimal schedule or exam predictor. Drawing is separately self-rated, never automatically graded. This is a study signal, not certified mastery.</p><p><a href="https://www.ncbi.nlm.nih.gov/sites/books/NBK1528/pdf/Bookshelf_NBK1528.pdf" target="_blank" rel="noopener">NCBI amino acid code reference</a><br><a href="https://openstax.org/books/biology-2e/pages/3-4-proteins" target="_blank" rel="noopener">OpenStax: proteins and amino acids</a></p><details><summary>Molecular structure sources (PubChem / ChEBI)</summary><ul>${window.AMINO_STRUCTURE_DATA.map(a=>`<li><a href="${a.sourceUrl}" target="_blank" rel="noopener">${a.name}</a></li>`).join('')}</ul></details>`);};$('#reset').onclick=()=>modal('<h2>Start fresh?</h2><p>This clears quiz progress and missed-answer history from this browser only.</p><button class="btn" id="confirmReset">Clear my practice progress</button>');$('#dialog').addEventListener('click',e=>{if(e.target.id==='confirmReset'){progress=emptyProgress();storageBlocked=false;save();$('#dialog').close();render();}});stats();render();storageNotice();
function progressTable(items,labels){return `<table><thead><tr><th>Amino acid</th>${Object.values(labels).map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${items.map(a=>`<tr><th><button class="progressname" data-level="${a.one}" aria-label="${a.name}: ${aminoLevel(a).label}. View next requirement">${a.name}<small>${levelBadge(a)}</small></button></th>${Object.keys(labels).map(k=>{const t=skill(a,k);return `<td class="${t.streak>=3?'secure':t.wrong&&t.streak===0?'needs':''}" title="${t.right} correct / ${t.wrong} misses / ${t.hinted} assisted">${t.streak>=3?'✓':t.streak||((t.right+t.wrong)?'↻':'—')}${t.delayedSuccess?' ↗'+t.delayedSuccess:''}${t.hinted?' ·h'+t.hinted:''}</td>`;}).join('')}</tr>`).join('')}</tbody></table>`;}
function dashboard(){const view=dashboardView||progress.lastAnswerFormat||progress.practiceFormat;const labels=view==='choice'?{choiceStructure:'Structure',choiceName:'Name',choiceThree:'3-letter',choiceOne:'1-letter',draw:'Draw*',forge:'Build*'}:{structure:'Structure',name:'Name',three:'3-letter',one:'1-letter',draw:'Draw*',forge:'Build*'};stage.innerHTML=`<div class="panel progresspanel"><div class="paneltop"><h2>Your skill inventory.</h2><span class="tag">ALL 20</span></div><div class="answerformats" role="group" aria-label="Progress evidence"><button id="progressChoices" class="btn light ${view==='choice'?'selected':''}" aria-pressed="${view==='choice'}">With choices</button><button id="progressTyped" class="btn light ${view==='typed'?'selected':''}" aria-pressed="${view==='typed'}">Without options</button></div><p class="caption">${view==='choice'?'Choice recognition is separate from unaided recall. ':'Typed recall and delayed checks. '}Each amino acid has its own recall level. Tap its name for the next goal. *Draw is self-rated. Build is group assembly, not full freehand recall.</p><div class="legend"><span>— Not tried</span><span>1–2 Building</span><span>✓ 3+ practice streak</span><span>↗ Delayed checks</span><span>h Assisted tries</span></div><div class="progressgrids">${progressTable(AMINO.slice(0,10),labels)}${progressTable(AMINO.slice(10),labels)}</div><p class="caption">↻ = revisit a miss. Old practice starts with zero delayed checks. Progress stays in this browser.</p><div class="row"><button class="btn" id="weakStart">Practice weak spots →</button><button class="btn light" id="progressDue">Due now (${dueItems().length})</button><button class="textbtn" id="rewards">Collection & badges</button></div><details class="backup"><summary>Backup / transfer progress</summary><p class="caption">Reloading restores this browser’s progress. Export a JSON file to back up or move devices. Import replaces this browser’s progress after confirmation. No student details included.</p><div class="row"><button class="btn light" id="exportProgress">Export backup</button><label class="btn light filelabel">Import backup<input type="file" id="importProgress" accept=".json,application/json"></label></div><p id="backupMessage" class="caption" role="status"></p></details></div>`;$('#progressChoices').onclick=()=>{dashboardView='choice';dashboard();};$('#progressTyped').onclick=()=>{dashboardView='typed';dashboard();};document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>levelDetails(AMINO.find(a=>a.one===b.dataset.level)));$('#progressDue').onclick=()=>{changeMode('quiz');startDue();};$('#rewards').onclick=showRewards;$('#exportProgress').onclick=exportProgress;$('#importProgress').onchange=importProgress;$('#weakStart').onclick=()=>{mode='quiz';topic='mixed';document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.mode==='quiz'));startRound(false,false);};}

const familyGroups=[{title:'Small & special',codes:['G','A','P'],cue:'Glycine has H as its side chain. Alanine adds one CH₃. Proline loops back to the nitrogen, so it is the special ring-shaped exception.'},{title:'Branched carbon chains',codes:['V','L','I'],cue:'Valine branches close to the backbone. Leucine adds CH₂ before the fork. Isoleucine moves the fork closer to the backbone.'},{title:'Hydroxyl (–OH)',codes:['S','T'],cue:'Serine has CH₂–OH. Threonine adds CH₃ to that carbon: CH(OH)–CH₃.'},{title:'Sulfur-containing',codes:['C','M'],cue:'Cysteine ends in –SH. Methionine has sulfur inside a longer chain: –CH₂–CH₂–S–CH₃.'},{title:'Acid ↔ amide pairs',codes:['D','N','E','Q'],cue:'Aspartic acid ↔ asparagine: swap side-chain –OH for –NH₂. Glutamic acid ↔ glutamine does the same, with one extra CH₂.'},{title:'Aromatic rings',codes:['F','Y','W'],cue:'Phenylalanine has one six-membered ring. Tyrosine adds –OH to that ring. Tryptophan has two fused rings, including a nitrogen.'},{title:'Basic side chains',codes:['K','R','H'],cue:'Lysine: long chain ending in NH₂. Arginine: three nitrogens in its end group. Histidine: a five-membered ring with two nitrogens.'}];
let familyIndex=0,familyMember=0;
function families(){const g=familyGroups[familyIndex];const members=[g.codes[familyMember],g.codes[(familyMember+1)%g.codes.length]];members.forEach(code=>expose(AMINO.find(a=>a.one===code)));stage.innerHTML=`<div class="panel familypanel"><div class="paneltop"><h2>One backbone. Change R.</h2><span class="tag">FAMILY LAB</span></div><div class="familybuttons" id="familyButtons" role="group" aria-label="Explore a structural family">${familyGroups.map((x,i)=>`<button class="btn light ${i===familyIndex?'active':''}" data-family="${i}" aria-pressed="${i===familyIndex}">${x.title}</button>`).join('')}</div><p class="familycue">${g.cue}</p><div class="comparegrid comparepair">${members.map(code=>{const a=AMINO.find(x=>x.one===code);return `<div>${img(a)}<b>${a.name}</b><div class="caption">${a.three} · ${a.one}</div></div>`;}).join('')}</div><div class="pagecontrols"><button class="btn light" id="familyPrev">← Previous</button><span class="caption">Side chain ${familyMember+1} / ${g.codes.length}</span><button class="btn" id="familyNext">Next →</button></div><details class="familyhelp"><summary>How the shared backbone works</summary><p class="caption">The central α-carbon connects to an amino group, a carboxyl group, H and a side chain (R). Glycine has R = H; proline loops R back to its nitrogen. These are selected comparisons, not exhaustive groups. The memory families overlap: tyrosine is aromatic and has –OH. The groups are learning aids, not an exclusive classification.</p>${convention}</details></div>`;document.querySelectorAll('[data-family]').forEach(b=>b.onclick=()=>{familyIndex=+b.dataset.family;familyMember=0;families();});$('#familyPrev').onclick=()=>{familyMember=(familyMember+g.codes.length-1)%g.codes.length;families();};$('#familyNext').onclick=()=>{familyMember=(familyMember+1)%g.codes.length;families();};}

function exportProgress(){const payload={format:'amino-quest-progress',version:1,exportedAt:new Date().toISOString(),progress:validateProgress(progress)};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='amino-quest-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('#backupMessage').textContent='Backup exported. Keep the JSON file to restore or transfer your progress.';}
function parseBackup(text){const raw=JSON.parse(text);if(raw.format!=='amino-quest-progress'||raw.version!==1)throw Error('This is not a supported Amino Quest backup.');return validateProgress(raw.progress);}
async function importProgress(e){const file=e.target.files[0];if(!file)return;try{if(file.size>2*1024*1024)throw Error('File is too large.');pendingImport=parseBackup(await file.text());modal('<h2>Replace progress?</h2><p>This replaces progress stored in this browser with your backup. Export your current progress first if you want to keep it.</p><div class="actions"><button class="btn light" id="cancelImport">Cancel</button><button class="btn" id="confirmImport">Replace with backup</button></div>');$('#cancelImport').onclick=()=>{pendingImport=null;$('#dialog').close();};$('#confirmImport').onclick=()=>{if(!pendingImport)return;progress=pendingImport;pendingImport=null;storageBlocked=false;save();$('#dialog').close();dashboard();$('.backup').open=true;$('#backupMessage').textContent=storageIssue||'Backup restored successfully.';};}catch(err){pendingImport=null;$('#backupMessage').textContent='Import stopped: '+err.message+' Your current progress was not changed.';}finally{e.target.value='';}}

function recordForge(result,persist=true){const a=AMINO.find(a=>a.one===result.code);if(!a)return;const t=skill(a,'forge');if(result.assisted||!result.firstAttempt)t.hinted++;else{t.streak=result.correct?t.streak+1:0;t[result.correct?'right':'wrong']++;if(result.correct&&result.mode==='challenge')t.assemblyAward=1;}if(persist)save();}
function renderForge(){if(!window.MoleculeForge){modal('<h2>Forge is loading.</h2><p>Refresh this page, then try again.</p>');return;}stage.innerHTML='<div class="panel forgepanel"><div class="paneltop"><h2>Molecule Forge</h2><button class="textbtn" id="backSketch">Back to blank drawing →</button></div><div id="forgeMount"></div></div>';$('#backSketch').onclick=()=>changeMode('draw');window.MoleculeForge.mount($('#forgeMount'),{initialCode:AMINO.find(a=>a.name===drawName)?.one||'A',initialRun:progress.forgeRun,weakCodes:AMINO.filter(a=>{const t=skill(a,'forge');return t.wrong&&t.streak===0;}).map(a=>a.one),onRunChange:snapshot=>{progress.forgeRun=snapshot?window.MoleculeForge.validateRun(snapshot):null;save();},onResult:recordForge,onExposure:event=>{const code=typeof event==='string'?event:event.code;const a=AMINO.find(a=>a.one===code);if(a)expose(a);},onDraw:code=>{const a=AMINO.find(a=>a.one===code);if(a){drawName=a.name;drawShown=false;drawScaffold=true;drawAssisted=true;paths=[];}changeMode('draw');}});}
// A finite mixed-mode quest, adapted from saved evidence at the start.
function questRun(){return progress.questRun;}
function questStage(){return questRun()?.queue[questRun().index];}
function isQuestTask(kind){return mode==='quest'&&questStage()?.kind===kind&&!questRun().complete;}
function startQuest(){stopResponseTiming();const due=dueItems();const items=AMINO.map(a=>({code:a.one,level:aminoLevel(a).index,skills:Object.fromEntries([...recallSkills,...choiceSkills,'draw','forge'].map(k=>[k,{...skill(a,k)}])),dueKinds:due.filter(q=>q.a.one===a.one).map(q=>q.kind)}));const queue=window.AminoQuestEngine.buildPlan({items,now:Date.now(),fluency:progress.fluency});progress.questRun={version:1,queue,index:0,paused:false,complete:false,results:[],current:window.AminoQuestEngine.defaultCurrent(queue[0].kind),rewardStart:rewardState().xp};mode='quest';round=null;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.mode==='quest'));save();renderQuest();}
function questKindLabel(kind,format){if(format==='choice')return {structure:'Identify a structure',fromcode:'Choose the full name',three:'Choose the 3-letter code',one:'Choose the 1-letter code'}[kind]||questKindLabel(kind);return {structure:'Identify a structure',fromcode:'Recall the full name',three:'Recall the 3-letter code',one:'Recall the 1-letter code',forge:'Build a molecule',draw:'Draw from memory'}[kind];}
function renderQuest(){const r=questRun();if(!r||r.paused&&!r.complete){stage.innerHTML=`<div class="panel questwelcome"><h2>${r?'Your quest is saved.':'One quest. Different ways to remember.'}</h2><p class="caption">Six short steps. Recall, build, draw.</p><div class="questpath"><span>⌁ Identify</span><span>A Name</span><span>Ala 3-letter</span><span>A 1-letter</span><span>⚒ Build</span><span>✎ Draw</span></div><details class="questmethod"><summary>How your next tasks are chosen</summary><p class="caption">The plan uses your progress at the start: due recall first, weak skills next, guided building for unfamiliar structures, and blank drawing for familiar ones. These are practical study rules, not a proven optimal sequence or exam prediction. Each step uses a different amino acid.</p></details><div class="actions"><button class="btn accent" id="questBegin">${r?'Resume step '+(r.index+1)+' of 6':'Start adaptive quest →'}</button>${r?'<button class="btn light" id="questRestart">Start a new quest</button>':''}</div></div>`;$('#questBegin').onclick=()=>{if(!r){startQuest();return;}r.paused=false;save();renderQuest();};if(r)$('#questRestart').onclick=()=>{modal('<h2>Replace this unfinished quest?</h2><p>Recorded skill progress stays. Only the remaining quest steps will be replaced.</p><button class="btn" id="replaceQuest">Start a new quest</button>');$('#replaceQuest').onclick=()=>{$('#dialog').close();startQuest();};};return;}if(r.complete){questRecap();return;}const s=questStage();if(s.kind==='forge'){questForge();return;}if(s.kind==='draw'){const c=r.current;drawName=AMINO.find(a=>a.one===s.code).name;drawShown=c.shown;drawScaffold=c.scaffold;drawAssisted=c.assisted;paths=c.paths.map(p=>p.map(x=>[...x]));draw();return;}const a=AMINO.find(a=>a.one===s.code);round={quest:true,exam:false,items:[{a,kind:s.kind}],i:0,answers:[],locked:false,confidence:null};question();}
function questFrame(){const r=questRun(),s=questStage(),next=r.queue[r.index+1];stage.insertAdjacentHTML('afterbegin',`<div class="questguide"><div><b>✦ Quest · ${r.index+1} / ${r.queue.length} · ${s.kind==='draw'?'Draw '+AMINO.find(a=>a.one===s.code).name+' from memory':questKindLabel(s.kind,r.current.answerFormat||s.answerFormat)}</b><details class="questwhy"><summary>Why this task?</summary><small>${window.AminoQuestEngine.reasonText(s)}</small></details><small>${next?'Next: '+questKindLabel(next.kind,next.answerFormat):'Next: recap'}</small></div><button class="btn light" id="questPause">Pause quest</button></div>`);$('#questPause').onclick=pauseQuest;}
function pauseQuest(){stopResponseTiming();const r=questRun();if(!r||r.complete)return;r.paused=true;round=null;save();renderQuest();}
function questSyncQuestion(){if(!round?.quest||!questRun()||questRun().current.answered)return;const c=questRun().current,q=round.items[0];c.input=($('#answer').value||'').slice(0,200);c.confidence=round.confidence;c.assisted=!!q.assisted;c.hintStage=q.hintStage;c.answerFormat=q.answerFormat;c.optionIds=[...(q.optionIds||[])];c.choiceViewed=!!q.choiceViewed;save();}
function bindQuestQuestion(){const c=questRun().current,q=round.items[0];$('#answer').value=c.input;$('#answer').oninput=questSyncQuestion;$('#exitRound').hidden=true;$('.questionpanel .paneltop').hidden=true;$('.questionpanel .bar').hidden=true;questFrame();if(c.answered){round.locked=true;lockAnswerControls(q);$('#answer').disabled=true;$('#check').disabled=true;$('#skip').hidden=true;$('#hintButton').hidden=true;$('#assistedNext').hidden=true;$('#feedback').innerHTML=`<div class="feedback ${c.correct?'':'wrong'}">${c.correct?'✓ Answer checked.':'The answer is '+expected(q)+'.'}${codeLookalikeHelp(q,c.input,c.correct)}<br>${q.a.name} · <span class="code-label">${q.a.three} · ${q.a.one}</span><p class="caption">${c.assisted?'Assisted practice. Revisit later without hints.':q.answerFormat==='choice'?'Choice recognition recorded.':'Unaided response recorded.'} Your saved result is not scored again on reload.</p></div>`;$('#continue').hidden=false;}else if(c.hintStage){q.hintStage=c.hintStage-1;showHint();}$('#continue').textContent=questRun().index===5?'Finish quest →':'Next quest step →';}
function questRecordRecall(q,v,ok,review,gained){const r=questRun();if(!round?.quest||r.current.answered)return;r.current.input=v.slice(0,200);r.current.confidence=round.confidence;r.current.assisted=!!q.assisted;r.current.hintStage=q.hintStage;r.current.answerFormat=q.answerFormat;r.current.optionIds=[...(q.optionIds||[])];r.current.choiceViewed=!!q.choiceViewed;r.current.answered=true;r.current.correct=ok;r.results.push({code:q.a.one,kind:q.kind,correct:ok,assisted:!!q.assisted,selfRated:false,skipped:!v,recognition:q.answerFormat==='choice',delayed:!!review.delayed,gained});save();}
function advanceQuest(){stopResponseTiming();const r=questRun();if(!r||r.complete||!r.current.answered)return;r.index++;round=null;if(r.index>=r.queue.length){r.complete=true;r.paused=false;}else r.current=window.AminoQuestEngine.defaultCurrent(r.queue[r.index].kind);save();renderQuest();}
function questForge(){const r=questRun(),s=questStage(),c=r.current,a=AMINO.find(a=>a.one===s.code);let pendingResult=null;stage.innerHTML='<div class="panel forgepanel"><div id="questForgeMount"></div></div>';questFrame();const initial=c.forgeRun||window.MoleculeForge.createRun([s.code],s.forgeMode);window.MoleculeForge.mount($('#questForgeMount'),{embedded:true,initialRun:initial,initialCode:s.code,onContinue:advanceQuest,onRunChange:snapshot=>{if(questRun()!==r||questStage()!==s)return;c.forgeRun=window.MoleculeForge.validateRun(snapshot);if(pendingResult&&!c.answered){const result=pendingResult;pendingResult=null;const before=rewardState().xp;recordForge(result,false);if(result.correct){c.answered=true;c.correct=true;c.assisted=!!result.assisted;r.results.push({code:s.code,kind:'forge',correct:true,assisted:c.assisted,selfRated:false,skipped:false,delayed:false,gained:rewardState().xp-before});}else c.assisted=true;}save();},onResult:result=>{if(questRun()!==r||c.answered)return;pendingResult={...result,assisted:result.assisted||c.assisted};},onExposure:()=>expose(a)});}
function persistQuestDraw(){if(!isQuestTask('draw'))return;const c=questRun().current;c.assisted=c.assisted||drawAssisted;c.scaffold=drawScaffold;c.shown=drawShown;const recent=paths.slice(-100),count=recent.reduce((n,p)=>n+p.length,0),step=Math.max(1,Math.ceil(count/4900));c.paths=recent.map(p=>p.filter((_,i)=>i%step===0).map(([x,y])=>[Math.round(Math.max(0,Math.min(1100,x))),Math.round(Math.max(0,Math.min(600,y)))])).filter(p=>p.length);save();}
function bindQuestDraw(){const r=questRun(),s=questStage(),c=r.current;$('#drawSelect').closest('.controls').hidden=true;$('.drawpanel .paneltop').hidden=true;$('#openForge').hidden=true;$('#gotDraw').textContent='My drawing matches';$('#againDraw').textContent='Needs another try';questFrame();for(const id of ['#scaffoldToggle','#revealDraw','#undo','#clear']){const original=$(id).onclick;$(id).onclick=()=>{if(c.answered)return;if(c.referenceSeen&&['#scaffoldToggle','#undo','#clear'].includes(id)){c.assisted=true;c.earlyReference=true;c.pendingDrawRating=null;drawAssisted=true;}original();if(id==='#revealDraw'&&drawShown)c.referenceSeen=true;persistQuestDraw();draw();};}$('#blankTry').onclick=()=>{if(c.answered)return;drawScaffold=false;drawShown=false;c.pendingDrawRating=null;c.earlyReference=c.earlyReference||c.referenceSeen;c.assisted=c.assisted||c.referenceSeen;drawAssisted=c.assisted;paths=[];persistQuestDraw();draw();};const down=$('#pad').onpointerdown;$('#pad').onpointerdown=e=>{if(c.answered)return;if(c.referenceSeen){c.assisted=true;c.earlyReference=true;c.pendingDrawRating=null;drawAssisted=true;$('#gotDraw').disabled=true;}down(e);persistQuestDraw();};const up=$('#pad').onpointerup;$('#pad').onpointerup=$('#pad').onpointercancel=e=>{up(e);persistQuestDraw();draw();};$('#earlyReference').onclick=()=>{if(c.answered)return;c.earlyReference=true;c.assisted=true;c.pendingDrawRating=null;c.referenceSeen=true;drawAssisted=true;drawShown=true;expose(AMINO.find(a=>a.one===s.code));persistQuestDraw();draw();};$('#gotDraw').onclick=()=>selectQuestDraw(true);$('#againDraw').onclick=()=>selectQuestDraw(false);if(!c.answered){drawRatingControls(c.pendingDrawRating,()=>commitQuestDraw(),!!c.earlyReference);}if(c.answered){for(const id of ['#gotDraw','#againDraw','#scaffoldToggle','#blankTry','#undo','#clear','#revealDraw','#earlyReference'])$(id).disabled=true;stage.insertAdjacentHTML('beforeend',`<div class="questendstep"><p>${c.assisted?'Assisted':'Blank-start'} drawing · self-rated ${c.correct?'matches':'needs practice'}. This is not an automatic correctness grade.</p><button class="btn" id="questDrawNext">${r.index===5?'Finish quest':'Next quest step'} →</button></div>`);$('#questDrawNext').onclick=advanceQuest;}}

function drawRatingControls(value,confirm,early=false){for(const [id,v] of [['#gotDraw',true],['#againDraw',false]]){const b=$(id);b.textContent=v?'My drawing matches':'Needs another try';b.setAttribute?.('aria-pressed',String(value===v));b.classList.toggle('rating-selected',value===v);if(v)b.disabled=early||!drawShown;}stage.insertAdjacentHTML('beforeend',`<div class="drawconfirmation"><p>${value===null?'Compare, then choose a rating.':value?'Selected: my drawing matches.':'Selected: needs another try.'}<small>${early?'Reference used before finishing: this is practice, not a correct recall.':'Not recorded yet. Tap again to undo, or change your choice.'}</small></p><button class="btn accent" id="confirmDrawing" ${value===null?'disabled':''}>Confirm & next →</button></div>`);$('#confirmDrawing').onclick=confirm;}
function selectQuestDraw(ok){const c=questRun()?.current;if(!isQuestTask('draw')||c.answered||(ok&&(c.earlyReference||!drawShown)))return;c.pendingDrawRating=c.pendingDrawRating===ok?null:ok;persistQuestDraw();draw();}
function commitQuestDraw(){const r=questRun();if(!isQuestTask('draw')||r.current.answered||r.current.pendingDrawRating===null||(r.current.pendingDrawRating&&r.current.earlyReference))return;const ok=r.current.pendingDrawRating;atomicProgress(()=>{finishQuestDraw(ok);advanceQuest();});}
function saveStandaloneDraft(){if(round?.focus&&round.items[round.i]?.kind==='draw'){if(standaloneEarlyReference)invalidateFocusCurrent();return;}const recent=paths.slice(-100),count=recent.reduce((n,p)=>n+p.length,0),step=Math.max(1,Math.ceil(count/4900));progress.drawDraft={name:drawName,rating:standalonePendingRating,shown:drawShown,scaffold:drawScaffold,assisted:drawAssisted,referenceSeen:standaloneReferenceSeen,earlyReference:standaloneEarlyReference,paths:recent.map(p=>p.filter((_,i)=>i%step===0).map(([x,y])=>[Math.round(Math.max(0,Math.min(1100,x))),Math.round(Math.max(0,Math.min(600,y)))]))};save();}
function selectStandaloneDraw(ok){if(ok&&(standaloneEarlyReference||!drawShown))return;standalonePendingRating=standalonePendingRating===ok?null:ok;saveStandaloneDraft();draw();}
function bindStandaloneDraw(){if(!round?.focus&&progress.drawDraft&&progress.drawDraft.name!==drawName){standalonePendingRating=null;standaloneReferenceSeen=false;standaloneEarlyReference=false;progress.drawDraft=null;save();}$('#earlyReference').onclick=()=>{standaloneEarlyReference=true;standaloneReferenceSeen=true;drawAssisted=true;standalonePendingRating=null;drawShown=true;expose(AMINO.find(a=>a.name===drawName));saveStandaloneDraft();draw();};$('#gotDraw').onclick=()=>selectStandaloneDraw(true);$('#againDraw').onclick=()=>selectStandaloneDraw(false);if(drawShown||standalonePendingRating!==null)drawRatingControls(standalonePendingRating,commitStandaloneDraw,standaloneEarlyReference);for(const id of ['#scaffoldToggle','#blankTry','#undo','#clear','#revealDraw','#randomDraw']){const original=$(id).onclick;$(id).onclick=()=>{standalonePendingRating=null;if(standaloneReferenceSeen&&['#scaffoldToggle','#blankTry','#undo','#clear'].includes(id)){drawAssisted=true;standaloneEarlyReference=true;}const assisted=drawAssisted;original();if(id==='#revealDraw'&&drawShown)standaloneReferenceSeen=true;if(id==='#blankTry'&&standaloneReferenceSeen)drawAssisted=assisted;if(id==='#randomDraw'){standaloneReferenceSeen=false;standaloneEarlyReference=false;}saveStandaloneDraft();draw();};}const change=$('#drawSelect').onchange;$('#drawSelect').onchange=e=>{standalonePendingRating=null;standaloneReferenceSeen=false;standaloneEarlyReference=false;change(e);saveStandaloneDraft();draw();};const down=$('#pad').onpointerdown,up=$('#pad').onpointerup;$('#pad').onpointerdown=e=>{standalonePendingRating=null;if(standaloneReferenceSeen){drawAssisted=true;standaloneEarlyReference=true;$('#gotDraw').disabled=true;}down(e);saveStandaloneDraft();};$('#pad').onpointerup=$('#pad').onpointercancel=e=>{up(e);saveStandaloneDraft();draw();};}
function commitStandaloneDraw(){if(round?.focus&&round.items[round.i]?.kind==='draw'){commitFocusDraw();return;}if(mode!=='draw'||standalonePendingRating===null||(standalonePendingRating&&standaloneEarlyReference))return;const ok=standalonePendingRating,a=AMINO.find(a=>a.name===drawName);atomicProgress(()=>{standalonePendingRating=null;progress.drawDraft=null;record(a,'draw',ok,{hinted:drawAssisted,retentionEligible:false});if(ok)drawName=AMINO[(AMINO.indexOf(a)+1)%20].name;drawScaffold=true;drawAssisted=true;standaloneReferenceSeen=false;standaloneEarlyReference=false;drawShown=false;paths=[];save();draw();});}

function finishQuestDraw(ok){const r=questRun();if(!isQuestTask('draw')||r.current.answered||(ok&&r.current.earlyReference))return;const a=AMINO.find(a=>a.one===questStage().code);persistQuestDraw();const c=r.current;c.pendingDrawRating=null;c.answered=true;c.correct=ok;r.results.push({code:a.one,kind:'draw',correct:ok,assisted:c.assisted,selfRated:true,skipped:false,delayed:false,gained:0});record(a,'draw',ok,{hinted:c.assisted,retentionEligible:false});save();draw();}
function questRecap(){const r=questRun(),choices=r.results.filter(x=>x.recognition),objective=r.results.filter(x=>!['draw','forge'].includes(x.kind)&&!x.recognition),unaided=objective.filter(x=>x.correct&&!x.assisted),assisted=objective.filter(x=>x.assisted),build=r.results.find(x=>x.kind==='forge'),drawing=r.results.find(x=>x.kind==='draw'),xp=r.results.reduce((n,x)=>n+x.gained,0),evo=evolutionStage(rewardState().xp),evolved=evo.index>evolutionStage(r.rewardStart).index;stage.innerHTML=`<div class="panel questrecap"><p class="eyebrow">SIX STEPS · ONE LEARNING JOURNEY</p><h2>Quest complete.</h2><div class="questreward"><span class="rewardportrait">${companionArt(evo.index)}</span><div><b>+${xp} earned milestone XP</b><small>${evolved?'Your companion evolved to '+evo.name+'!':'Every attempt helps choose the next useful practice.'}</small></div></div><div class="questtotals"><div><b>${unaided.length} / ${objective.length}</b><span>typed recall correct without hints</span></div><div><b>${choices.filter(x=>x.correct&&!x.assisted).length} / ${choices.length}</b><span>choice recognition correct without hints</span></div><div><b>${assisted.length}</b><span>assisted recall attempts</span></div><div><b>${objective.filter(x=>x.delayed).length}</b><span>delayed checks passed</span></div></div><p class="caption">Build: ${build?.assisted?'guided / assisted':'challenge, first-check'}. Drawing: ${drawing?.assisted?'assisted':'blank-start'}, self-rated ${drawing?.correct?'matches':'needs another try'}. These do not count as objective recall mastery.</p><details><summary>Your six steps</summary>${r.results.map(x=>`<p class="caption">${AMINO.find(a=>a.one===x.code).name} · ${questKindLabel(x.kind,x.recognition?'choice':'typed')} · ${x.selfRated?'self-rated':x.assisted?'assisted':x.correct?'correct':'revisit'}</p>`).join('')}</details><p class="caption">Take a short break. Return to Due now for later checks, or start a fresh plan from your updated progress. Mistakes cost no points; repeating easy steps cannot farm milestone XP.</p><div class="actions"><button class="btn accent" id="anotherQuest">New adaptive quest</button><button class="btn light" id="questDue">Due now (${dueItems().length})</button><button class="btn light" id="questInventory">View individual progress</button></div></div>`;$('#anotherQuest').onclick=startQuest;$('#questDue').onclick=()=>{changeMode('quiz');startDue();};$('#questInventory').onclick=()=>changeMode('progress');}
function classificationBadges(a){const groups=[['Aromatic','FYW H'.replace(/ /g,'')],['Sulfur-containing','CM'],['Branched-chain','VLI'],['Amide','NQ'],['Hydroxyl (–OH)','STY']].filter(([,codes])=>codes.includes(a.one));return `<div class="classification"><button id="classificationHelp" title="Classification details" class="classbadge class-${a.group.toLowerCase().replace(/ /g,'-')}">${a.group}</button>${groups.map(([label])=>`<button class="groupbadge" data-group="${label}" title="About ${label}">${label}</button>`).join('')}</div>`;}
function classificationHelp(code){const a=AMINO.find(a=>a.one===code);const caveat={H:'Histidine is in the basic family; its side-chain charge varies with pH and it is often uncharged near physiological pH. Its imidazole ring is aromatic.',Y:'Tyrosine is polar uncharged here because of its –OH, and also aromatic. Some charts group it with aromatics or hydrophobic residues.',W:'Tryptophan is usually grouped as nonpolar; its ring NH can still form hydrogen bonds.',C:'Cysteine is polar uncharged in this convention; its –SH is weakly acidic and can lose H⁺ at higher pH.'};expose(a);modal(`<h2>${a.name} · ${a.group}</h2><p class="classreason">${WHY_CLASS[code]}</p><details><summary>More about these groups</summary><p>${caveat[code]||'Look at R, not the shared backbone: consider charge, hydrogen bonding and the balance of polar groups versus hydrocarbon.'}</p><p>Classes describe side chains in a common near-neutral-pH study convention. Acidic and basic side chains are also polar. Secondary groups overlap; drawings here use neutral forms. Follow your teacher’s grouping if different. Code highlights are spelling or memory cues, not historical derivations.</p><p><a href="https://openstax.org/books/biology-2e/pages/3-4-proteins" target="_blank" rel="noopener">OpenStax: side-chain classes</a> · <a href="https://www.ebi.ac.uk/training/online/courses/foundations-protein-structure/fundamentals-of-protein-composition/the-building-blocks-amino-acids/general-structure/" target="_blank" rel="noopener">EMBL-EBI: side-chain chemistry</a></p></details>`);}
function referenceAssistance(){if(round?.focus){invalidateFocusCurrent();if(focusReferenceHelp())return;}if(round&&!round.exam&&!round.locked&&round.items[round.i]){if(!round.items[round.i].assisted)noteResponseSupport(round.items[round.i]);round.items[round.i].assisted=true;if(round.quest)questSyncQuestion();$('#hintText').textContent='Reference opened: this response is assisted practice, not independent recall.';}if(mode==='quest'&&questRun()&&!questRun().complete&&!questRun().current.answered){questRun().current.assisted=true;save();}}
const WHY_CLASS={A:'Its methyl (–CH₃) side chain contains only carbon and hydrogen, with no polar functional group.',R:'Its guanidine end group accepts H⁺ and is usually positively charged near neutral pH, making it basic.',N:'Its –C(=O)NH₂ amide can hydrogen-bond but is normally uncharged; its nitrogen is not basic like a free amine.',D:'Its extra side-chain carboxyl group can lose H⁺ and is usually –COO⁻ near neutral pH, making it acidic.',C:'Its thiol (–SH) gives some polarity and is usually uncharged near neutral pH, so we group it as polar uncharged.',E:'Like aspartic acid, its extra side-chain carboxyl group usually loses H⁺ near neutral pH; the extra CH₂ does not change its acidic class.',Q:'Its side-chain amide can hydrogen-bond without normally carrying a charge; an extra CH₂ compared with asparagine does not change its class.',G:'Its R group is just H, with no polar side-chain functional group, so it belongs in this convention’s nonpolar group.',H:'An imidazole-ring nitrogen can accept H⁺, placing it in the basic family even though the side chain is often uncharged near physiological pH.',I:'Its branched side chain contains only carbon and hydrogen, making it hydrophobic and nonpolar.',L:'Its branched hydrocarbon side chain has no polar functional group, so it is nonpolar.',K:'Its terminal side-chain amino group accepts H⁺ and is usually –NH₃⁺ near neutral pH, making it basic.',M:'Its sulfur is inside a thioether (C–S–C), not a terminal –SH, and the side chain is overall hydrophobic.',F:'Its benzene ring and CH₂ linker contain only carbon and hydrogen, giving a hydrophobic, nonpolar side chain.',P:'Its three-CH₂ loop is hydrocarbon; the nitrogen it joins belongs to the shared amino backbone, so proline is classed as nonpolar.',S:'Its side-chain –OH can hydrogen-bond with water while remaining uncharged near neutral pH.',T:'Its –OH allows hydrogen bonding with water; the extra CH₃ does not remove its polar, uncharged character.',W:'Its large fused-ring system is overall hydrophobic despite an NH that can hydrogen-bond, so this convention groups it as nonpolar.',Y:'Its phenolic –OH can hydrogen-bond and is usually uncharged near neutral pH, so this convention calls it polar uncharged despite its aromatic ring.',V:'Its forked side chain contains only carbon and hydrogen, with no polar functional group.'};
const SHORT_CLASS={A:'Methyl group: only carbon and hydrogen.',R:'Three-nitrogen end group: usually positively charged.',N:'Amide: hydrogen bonding, normally uncharged.',D:'Extra carboxyl group: usually negatively charged.',C:'–SH: some polarity, usually uncharged.',E:'Extra carboxyl group: usually negatively charged.',Q:'Amide: hydrogen bonding, normally uncharged.',G:'R = H: no polar side-chain group.',H:'Ring nitrogen accepts H⁺; charge varies.',I:'Hydrocarbon branches: only carbon and hydrogen.',L:'Hydrocarbon branches: only carbon and hydrogen.',K:'Terminal amino group: usually positively charged.',M:'Internal sulfur; overall hydrophobic side chain.',F:'Hydrocarbon ring: overall nonpolar.',P:'Hydrocarbon loop; its N belongs to the backbone.',S:'–OH: hydrogen bonding, normally uncharged.',T:'–OH: hydrogen bonding, normally uncharged.',W:'Large fused rings: hydrophobic overall, despite polar NH.',Y:'Ring –OH: hydrogen bonding, normally uncharged.',V:'Hydrocarbon branches: only carbon and hydrogen.'};

function groupHelp(a,label){const info={
'Aromatic':['Look for an alternating-bond ring. Aromatic describes a ring structure, not its polarity.',{F:'A six-carbon benzene ring.',Y:'A benzene ring with OH: aromatic and polar uncharged here.',W:'A fused two-ring indole with one NH; overall hydrophobic.',H:'A five-membered imidazole ring with two nitrogens; aromatic and basic.'}],
'Sulfur-containing':['Look for S in the side chain. Its bonds matter, not just the symbol.',{C:'A terminal thiol, –SH. Two cysteine thiols can form a disulfide bond.',M:'A thioether, C–S–C, inside an overall nonpolar side chain.'}],
'Branched-chain':['Look for a fork at a side-chain CH. The standard branched-chain group is valine, leucine and isoleucine.',{V:'The fork starts immediately: –CH(CH₃)₂.',L:'One CH₂ spacer comes before the fork: –CH₂–CH(CH₃)₂.',I:'The immediate fork has unequal arms: –CH(CH₃)–CH₂–CH₃.'}],
'Amide':['Find –C(=O)NH₂: N must join the carbonyl carbon directly. This group can hydrogen-bond but is normally uncharged; its N is not basic like a free amine.',{N:'One CH₂ before the amide.',Q:'Two CH₂ groups before the amide.'}],
'Hydroxyl (–OH)':['Find a side-chain OH outside a carboxyl (COOH) group. It can hydrogen-bond with water.',{S:'An alcohol OH on –CH₂OH.',T:'An alcohol OH on –CH(OH)CH₃, beside a methyl group.',Y:'A phenol OH directly on the aromatic ring.'}]};const entry=info[label];if(!entry)return;expose(a);modal(`<h2>${label}</h2><p>${entry[0]}</p><p><b>${a.name}:</b> ${entry[1][a.one]||''}</p>`);}

function comparisonPairs(a){return (typeof window!=='undefined'&&window.AMINO_COMPARISONS||[]).filter(p=>p.codes.includes(a.one));}
function compareCard(a,pairId){const pairs=comparisonPairs(a),pair=pairs.find(p=>p.id===pairId)||pairs[0];if(!pair)return;for(const code of pair.codes)expose(AMINO.find(x=>x.one===code));modal(`<h2>${pair.title}</h2>${pairs.length>1?`<div class="answerformats">${pairs.map(p=>`<button class="btn light ${p.id===pair.id?'selected':''}" data-compare="${p.id}" aria-pressed="${p.id===pair.id}">${p.title}</button>`).join('')}</div>`:''}<p class="comparecaption">${pair.caption}</p><div class="comparepair">${pair.members.map(m=>`<figure><figcaption><b>${m.name}</b> · ${m.three}</figcaption><img src="${m.svg}" alt="${m.name}: highlighted comparison region" width="${pair.svgWidth}" height="${pair.svgHeight}"></figure>`).join('')}</div><p class="caption">Amber marks the difference to notice. Both structures use the same scale.</p>`);document.querySelectorAll('[data-compare]').forEach(b=>b.onclick=()=>compareCard(a,b.dataset.compare));}

function renderFoundations(){stage.innerHTML='<div class="foundationspanel"><div id="foundationsMount"></div></div>';if(!window.AminoFoundations){$('#foundationsMount').innerHTML='<h2>Basics is loading.</h2><p>Refresh this page to continue.</p>';return;}window.AminoFoundations.mount($('#foundationsMount'),{initialState:progress.foundations,onExposure:code=>{const a=AMINO.find(a=>a.one===code);if(a)expose(a);},onStateChange:raw=>{const state=window.AminoFoundations.validateState(raw);if(state){progress.foundations=state;save();}},onForge:code=>{if(['A','S','C'].includes(code))renderBasicsBuild(code);},onExit:()=>changeMode('learn')});}
