// Active response time is local supporting evidence, never a countdown or mastery penalty.
function adaptiveItem(a){return {code:a.one,level:aminoLevel(a).index,skills:Object.fromEntries([...recallSkills,...choiceSkills].map(k=>[k,{...skill(a,k)}]))};}
function responseNow(){return typeof performance!=='undefined'&&typeof performance.now==='function'?performance.now():Date.now();}
function responseEnvironment(){return {visible:document.visibilityState!=='hidden',focused:typeof document.hasFocus==='function'?document.hasFocus():true};}
function syncResponseTiming(){if(responseTimer&&round?.quest&&responseOwner===round.items[round.i]&&questRun())questRun().current.responseTimer=responseTimer.snapshot();}
function stopResponseTiming(){if(responseTimer){responseTimer.pause();syncResponseTiming();}responseTimer=null;responseOwner=null;}
function startResponseTiming(q,reformat=false){const f=typeof window!=='undefined'?window.AminoFluency:null;if(!f||round?.locked||!recallSkills.includes(quizSkill(q.kind)))return;if(responseOwner===q&&responseTimer&&!reformat)return;stopResponseTiming();const c=round.quest?questRun().current:null;responseTimer=c&&(c.responseTimer||q.resumeTiming)?f.restoreTimer(c.responseTimer&&!c.responseTimer.paused&&!c.responseTimer.completed?{...c.responseTimer,valid:false,reason:'invalid-snapshot'}:c.responseTimer,{now:responseNow}):f.createTimer({now:responseNow,...responseEnvironment()});responseOwner=q;responseTimer.setEnvironment(responseEnvironment());responseTimer.resume();syncResponseTiming();if(c)save();}
function noteResponseSupport(q){const f=typeof window!=='undefined'?window.AminoFluency:null;if(!q?.a||!recallSkills.includes(quizSkill(q.kind)))return;if(typeof invalidateFocusEvidence==='function')invalidateFocusEvidence(q.a.one,quizSkill(q.kind));if(f)progress.fluency=f.noteSupport(progress.fluency,{code:q.a.one,skill:quizSkill(q.kind),format:q.answerFormat||'typed',now:Date.now()});}
function finishResponseTiming(q,ok){const f=typeof window!=='undefined'?window.AminoFluency:null;if(!f||!recallSkills.includes(quizSkill(q.kind)))return;const timing=responseOwner===q&&responseTimer?responseTimer.complete():null;syncResponseTiming();const attempt={code:q.a.one,skill:quizSkill(q.kind),format:q.answerFormat,correct:ok,hinted:!!q.assisted,retries:q.retry?1:0,timing,now:Date.now()};q.fluencySignal=f.getFluencySignal(progress.fluency,attempt);q.activeResponse=timing;progress.fluency=f.recordAttempt(progress.fluency,attempt);}
function responseEnvironmentChanged(){if(!responseTimer)return;responseTimer.setEnvironment(responseEnvironment());syncResponseTiming();if(round?.quest)save();}
if(document.addEventListener)document.addEventListener('visibilitychange',responseEnvironmentChanged);
if(typeof window!=='undefined'&&window.addEventListener){window.addEventListener('blur',()=>{if(responseTimer){responseTimer.setFocused(false);syncResponseTiming();if(round?.quest)save();}});window.addEventListener('focus',responseEnvironmentChanged);window.addEventListener('pageshow',()=>{if(responseTimer&&round&&!round.locked&&responseOwner===round.items[round.i]&&(!round.quest||!questRun().paused)){responseTimer.setEnvironment(responseEnvironment());responseTimer.resume();syncResponseTiming();if(round.quest)save();}});window.addEventListener('pagehide',()=>{if(responseTimer){responseTimer.pause();syncResponseTiming();if(round?.quest)save();}});}
function fluencyDetails(a){const f=typeof window!=='undefined'?window.AminoFluency:null;if(!f)return '';const rows=[];for(const k of recallSkills)for(const format of ['choice','typed']){const r=f.getRecord(progress.fluency,{code:a.one,skill:k,format});if(!r.attempts&&!r.supportEvents)continue;const times=[...r.cleanTimes].sort((a,b)=>a-b),typical=times.length?(times[Math.floor((times.length-1)/2)]+times[Math.floor(times.length/2)])/2:null;rows.push(`<div><b>${SKILL_NAMES[k]} · ${format==='choice'?'4 choices':'typed'}</b><span>${r.cleanCorrect} clean correct · ${r.hintedAttempts} assisted answers · ${r.supportEvents} help requests · ${r.retryAttempts} retries${typical!==null?` · ${times.length<5?'recent median active time':'typical active time'} ${(typical/1000).toFixed(1)}s (${times.length} recent clean answers)`:''}</span></div>`);}return `<details class="fluencydetails"><summary>Learning signals & active answer time</summary><p class="caption">Accuracy, hints, retries and recent clean answers guide practice. Time counts only while this page is visible and focused, excluding pauses. Each skill and answer format is compared only with itself. Slower correct answers keep full credit; timing never changes mastery or XP. No exam prediction.</p><div class="levelskills">${rows.join('')||'<p>No response signals recorded yet.</p>'}</div></details>`;}

function atomicProgress(action){saveDepth++;try{return action();}finally{saveDepth--;if(!saveDepth)save();}}

function classificationStats(a){return progress.classification[a.one]||{right:0,wrong:0,assisted:0};}
function classificationEvidence(a){const t=classificationStats(a);return `<p class="caption"><b>Classification sorting:</b> ${t.right} first-try correct · ${t.wrong} needed review · ${t.assisted} assisted. Separate from name/code/structure recall.</p>`;}
function classificationRecords(){atomicProgress(()=>AMINO.forEach(a=>expose(a,['name'])));modal(`<h2>Classification practice</h2><p class="caption">Completed sorting rounds. Corrections and hints do not count as first-try answers. Separate from recall levels and XP.</p><div class="classification-records">${AMINO.map(a=>`<div><b>${a.name}</b><span>${classificationStats(a).right} first try · ${classificationStats(a).wrong} corrected · ${classificationStats(a).assisted} assisted</span></div>`).join('')}</div>`);}
function classificationTotals(){const t=Object.values(progress.classification);return `${t.reduce((n,x)=>n+x.right,0)} first-try correct · ${t.reduce((n,x)=>n+x.wrong,0)} needed review`;}
function renderClassification(){classificationGame?.destroy?.();stage.innerHTML=`<div class="classifystats"><span id="classifySummary">${classificationTotals()}</span><button class="btn light" id="classificationRecords">Your classification progress</button></div><div id="classificationHost"></div>`;$('#classificationRecords').onclick=classificationRecords;if(!window.ClassificationSort){$('#classificationHost').innerHTML='<p>Reload to load the classification game.</p>';return;}classificationGame=window.ClassificationSort.mount($('#classificationHost'),{amino:AMINO,snapshot:progress.sortRun,onExposure:({code,keys})=>{const a=AMINO.find(x=>x.one===code);if(a)expose(a,keys?.includes('name')?['name']:[]);},onChange:snapshot=>{const checked=window.ClassificationSort.validateSnapshot(snapshot);if(!checked)return;progress.sortRun=checked;if(checked.phase==='question'&&checked.current?.attempts>0&&progress.focusState)invalidateFocusEvidence(checked.queue[checked.index],'classify');save();},onRound:recordClassification,onFinish:()=>{}});}
function recordClassification(result){const check=window.ClassificationSort?.validateSnapshot,next=check?.(result?.snapshot),previous=progress.sortRun;if(!next||!previous||next.id!==previous.id||next.phase!=='feedback'||next.index!==previous.index||previous.phase!=='question'||next.results.length!==previous.results.length+1||JSON.stringify(next.queue)!==JSON.stringify(previous.queue)||JSON.stringify(next.results.slice(0,-1))!==JSON.stringify(previous.results))return false;const item=next.results[next.index];if(result.id!==`${next.id}:${next.index}`||item.code!==result.code||item.attempts!==previous.current.attempts+1||(previous.current.firstGroup!==null&&item.firstGroup!==previous.current.firstGroup))return false;atomicProgress(()=>{const t=progress.classification[item.code]||(progress.classification[item.code]={right:0,wrong:0,assisted:0});if(item.correct&&!item.assisted)t.right++;else t.wrong++;if(item.assisted)t.assisted++;if((!item.correct||item.assisted)&&progress.focusState)invalidateFocusEvidence(item.code,'classify');progress.sortRun=next;});const summary=$('#classifySummary');if(summary)summary.textContent=classificationTotals();return true;}

function codeLookalikeHelp(q,value,ok){if(ok||q.a.one!=='I')return '';const v=String(value).trim().toLowerCase();return (q.kind==='three'&&v==='lle')||(q.kind==='one'&&v==='l')?'<br><strong>Isoleucine starts with the letter i, not L. Its codes are <span class="code-label">Ile</span> and <span class="code-label">I</span>.</strong>':'';}
